css:
/* Maison Vérel — domain-warped silk behind serif type.
   Re-theme: override --bkh-warp-c0 (ground), -c1 (body), -c2 (accent), -c3 (highlight/ink).
   The WebGL shader reads these same four variables, so the silk follows the theme. */
@property --bkh-warp-a { syntax: "<angle>"; inherits: false; initial-value: 0deg; }

.bkh-warp {
  --bkh-warp-c0: oklch(0.17 0.045 25);
  --bkh-warp-c1: oklch(0.39 0.13 30);
  --bkh-warp-c2: oklch(0.76 0.135 62);
  --bkh-warp-c3: oklch(0.95 0.03 85);
  --bkh-warp-line: color-mix(in oklch, var(--bkh-warp-c3) 20%, transparent);
  --bkh-warp-soft: color-mix(in oklch, var(--bkh-warp-c3) 74%, transparent);
  --bkh-warp-ease: cubic-bezier(.22, 1, .36, 1);
  --bkh-warp-serif: ui-serif, "New York", "Iowan Old Style", Georgia, serif;

  container-type: inline-size;
  container-name: bkh-warp;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  width: 100%;
  border-radius: 18px;
  background: var(--bkh-warp-c0);
  color: var(--bkh-warp-c3);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  &[data-scent="fig"] {
    --bkh-warp-c0: oklch(0.18 0.03 155);
    --bkh-warp-c1: oklch(0.40 0.075 140);
    --bkh-warp-c2: oklch(0.80 0.10 112);
    --bkh-warp-c3: oklch(0.96 0.025 95);
  }
  &[data-scent="iris"] {
    --bkh-warp-c0: oklch(0.19 0.014 330);
    --bkh-warp-c1: oklch(0.43 0.055 345);
    --bkh-warp-c2: oklch(0.80 0.05 25);
    --bkh-warp-c3: oklch(0.96 0.012 80);
  }

  & :where(a) { color: inherit; text-decoration: none; }
  & :focus-visible { outline: 2px solid var(--bkh-warp-c2); outline-offset: 3px; border-radius: 6px; }
}

.bkh-warp__gl {
  position: absolute; inset: 0; z-index: 0;
  width: 100%; height: 100%; display: block;
}
.bkh-warp__veil {
  position: absolute; inset: 0; z-index: 0; pointer-events: none;
  background:
    linear-gradient(100deg, color-mix(in oklch, var(--bkh-warp-c0) 78%, transparent) 0%, color-mix(in oklch, var(--bkh-warp-c0) 30%, transparent) 46%, transparent 72%),
    linear-gradient(0deg, color-mix(in oklch, var(--bkh-warp-c0) 55%, transparent), transparent 40%);
}

/* No WebGL (or the browser reclaimed the context): a slow conic silk in plain CSS. */
.bkh-warp.is-flat .bkh-warp__gl { display: none; }
.bkh-warp.is-flat::before {
  content: ""; position: absolute; inset: -25%; z-index: 0;
  background:
    radial-gradient(40% 45% at 72% 38%, var(--bkh-warp-c2), transparent 70%),
    radial-gradient(45% 55% at 38% 72%, var(--bkh-warp-c1), transparent 72%),
    conic-gradient(from var(--bkh-warp-a) at 60% 50%, var(--bkh-warp-c0), var(--bkh-warp-c1), var(--bkh-warp-c0), var(--bkh-warp-c2), var(--bkh-warp-c0));
  filter: blur(48px) saturate(1.1);
  animation: bkh-warp-spin 30s linear infinite;
}
@keyframes bkh-warp-spin { to { --bkh-warp-a: 360deg; } }

.bkh-warp__in {
  position: relative; z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "bar" "copy" "card";
  gap: clamp(36px, 7cqi, 72px);
  padding: clamp(18px, 4.6cqi, 56px);
  padding-bottom: clamp(24px, 5cqi, 56px);
}

/* ---- top bar ---- */
.bkh-warp__bar {
  grid-area: bar;
  display: flex; align-items: center; gap: 24px;
  font-size: 13px; letter-spacing: .02em;
}
.bkh-warp__brand {
  display: inline-flex; align-items: center; gap: 10px;
  font-family: var(--bkh-warp-serif); font-size: 17px; letter-spacing: .01em;
  & svg { width: 28px; height: 28px; fill: none; stroke: currentColor; stroke-width: 1.25; stroke-linecap: round; stroke-linejoin: round; }
}
.bkh-warp__nav {
  display: none; gap: 26px; margin-inline: auto;
  & a { color: var(--bkh-warp-soft); transition: color .3s var(--bkh-warp-ease); }
  & a:hover { color: var(--bkh-warp-c3); }
}
.bkh-warp__bag {
  margin-inline-start: auto;
  display: inline-flex; align-items: center; gap: 8px;
  padding: 7px 12px 7px 14px; border-radius: 999px; border: 1px solid var(--bkh-warp-line);
  transition: border-color .3s var(--bkh-warp-ease), background .3s var(--bkh-warp-ease);
  & span { font-variant-numeric: tabular-nums; display: inline-grid; place-items: center; min-width: 20px; height: 20px; border-radius: 999px; background: var(--bkh-warp-c3); color: var(--bkh-warp-c0); font-size: 11px; font-weight: 600; }
  &:hover { border-color: var(--bkh-warp-soft); background: color-mix(in oklch, var(--bkh-warp-c3) 8%, transparent); }
}

/* ---- copy ---- */
/* the copy column is its own container: the headline sizes to the column it sits in */
.bkh-warp__copy { grid-area: copy; align-self: end; max-width: 760px; container-type: inline-size; }
.bkh-warp__eyebrow {
  margin: 0 0 22px; display: flex; flex-wrap: wrap; align-items: center; gap: 12px;
  font-size: 11px; font-weight: 500; letter-spacing: .24em; text-transform: uppercase; color: var(--bkh-warp-soft);
  & span + span::before { content: ""; display: inline-block; width: 28px; height: 1px; margin-inline-end: 12px; vertical-align: middle; background: currentColor; opacity: .6; }
}
.bkh-warp__title {
  margin: 0;
  font-family: var(--bkh-warp-serif);
  font-weight: 400;
  font-size: clamp(2.3rem, 13.4cqi, 6.6rem);
  line-height: .94;
  letter-spacing: -.028em;
  text-wrap: balance;
  & span, & em { display: block; }
  & em { font-style: italic; color: var(--bkh-warp-c2); transition: color 1.2s var(--bkh-warp-ease); padding-inline-start: .4em; }
}
.bkh-warp__lede {
  margin: 26px 0 0; max-width: 44ch;
  font-size: clamp(15px, 13px + .45cqi, 17.5px); line-height: 1.6; text-wrap: pretty;
  color: var(--bkh-warp-soft);
}
.bkh-warp__cta { margin-top: 32px; display: flex; flex-wrap: wrap; align-items: center; gap: 14px 26px; }
.bkh-warp__btn {
  display: inline-flex; align-items: center; gap: 12px;
  padding: 15px 22px 15px 24px; border-radius: 999px;
  background: var(--bkh-warp-c3); color: var(--bkh-warp-c0);
  font-size: 14.5px; font-weight: 600; letter-spacing: .01em;
  transition: background .4s var(--bkh-warp-ease), scale .4s var(--bkh-warp-ease);
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; transition: translate .4s var(--bkh-warp-ease); }
  &:hover { background: color-mix(in oklch, var(--bkh-warp-c3), var(--bkh-warp-c2) 35%); }
  &:hover svg { translate: 4px 0; }
  &:active { scale: .97; }
}
.bkh-warp__link {
  font-size: 14px; color: var(--bkh-warp-soft);
  background: linear-gradient(currentColor, currentColor) 0 100% / 100% 1px no-repeat;
  padding-bottom: 3px;
  transition: color .3s, background-size .5s var(--bkh-warp-ease);
  &:hover { color: var(--bkh-warp-c3); background-size: 0% 1px; background-position: 100% 100%; }
}

/* ---- scent card ---- */
.bkh-warp__card {
  grid-area: card; align-self: end;
  padding: 18px 18px 16px;
  border-radius: 16px;
  border: 1px solid var(--bkh-warp-line);
  background: color-mix(in oklch, var(--bkh-warp-c0) 58%, transparent);
  backdrop-filter: blur(18px) saturate(1.15);
}
.bkh-warp__pick {
  margin: 0; padding: 0; border: 0; min-width: 0;
  display: grid; gap: 4px;
  & legend { padding: 0 0 10px; font-size: 11px; letter-spacing: .22em; text-transform: uppercase; color: var(--bkh-warp-soft); }
}
.bkh-warp__opt {
  position: relative;
  display: grid; grid-template-columns: 56px 1fr auto; align-items: center;
  padding: 11px 12px; border-radius: 10px; cursor: pointer;
  transition: background .35s var(--bkh-warp-ease);
  & input { position: absolute; opacity: 0; inset: 0; margin: 0; cursor: pointer; accent-color: var(--bkh-warp-c2); }
  &:hover { background: color-mix(in oklch, var(--bkh-warp-c3) 6%, transparent); }
  &:has(input:checked) { background: color-mix(in oklch, var(--bkh-warp-c3) 11%, transparent); }
  &:has(input:focus-visible) { outline: 2px solid var(--bkh-warp-c2); outline-offset: 1px; }
}
.bkh-warp__no { font: 500 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .04em; color: var(--bkh-warp-soft); font-variant-numeric: tabular-nums; }
.bkh-warp__nm { font-family: var(--bkh-warp-serif); font-size: 19px; }
.bkh-warp__dot {
  width: 9px; height: 9px; border-radius: 50%;
  border: 1px solid var(--bkh-warp-soft);
  transition: background .4s var(--bkh-warp-ease), border-color .4s, scale .5s cubic-bezier(.34, 1.56, .64, 1);
  scale: .7;
}
.bkh-warp__opt:has(input:checked) .bkh-warp__dot { background: var(--bkh-warp-c2); border-color: var(--bkh-warp-c2); scale: 1; }

.bkh-warp__notes { margin: 14px 0 0; padding: 14px 4px 0; border-top: 1px solid var(--bkh-warp-line); display: grid; gap: 9px; }
.bkh-warp__row {
  display: grid; grid-template-columns: 56px 1fr; gap: 0 12px; align-items: baseline;
  transition: opacity .7s var(--bkh-warp-ease), translate .7s var(--bkh-warp-ease), filter .7s var(--bkh-warp-ease);
  transition-delay: calc(var(--i) * 80ms + 60ms);
  @starting-style { opacity: 0; translate: 0 10px; filter: blur(5px); }
  & dt { font-size: 10.5px; letter-spacing: .2em; text-transform: uppercase; color: var(--bkh-warp-soft); }
  & dd { margin: 0; font-size: 14px; line-height: 1.45; text-wrap: pretty; }
}
.bkh-warp__price {
  margin: 14px 0 0; padding: 12px 4px 0; border-top: 1px solid var(--bkh-warp-line);
  display: flex; justify-content: space-between; align-items: baseline; gap: 12px;
  font-size: 12.5px; color: var(--bkh-warp-soft);
  & b { font-family: var(--bkh-warp-serif); font-weight: 400; font-size: 22px; color: var(--bkh-warp-c3); font-variant-numeric: tabular-nums lining-nums; }
}

/* ---- entrance: lines rise out of a clip, staggered by --i ---- */
.bkh-warp__eyebrow, .bkh-warp__lede, .bkh-warp__cta, .bkh-warp__card {
  transition: opacity 1s var(--bkh-warp-ease), translate 1.1s var(--bkh-warp-ease);
  transition-delay: calc(var(--i) * 90ms + 150ms);
  @starting-style { opacity: 0; translate: 0 18px; }
}
.bkh-warp__title span, .bkh-warp__title em {
  transition: clip-path 1.2s var(--bkh-warp-ease), translate 1.2s var(--bkh-warp-ease), color 1.2s var(--bkh-warp-ease);
  transition-delay: calc(var(--i) * 110ms + 120ms), calc(var(--i) * 110ms + 120ms), 0ms;
  clip-path: inset(-0.2em -0.2em -0.25em -0.2em);
  @starting-style { clip-path: inset(-0.2em -0.2em 100% -0.2em); translate: 0 .5em; }
}

@container bkh-warp (min-width: 560px) {
  .bkh-warp__nav { display: flex; }
  .bkh-warp__bag { margin-inline-start: 0; }
}
@container bkh-warp (min-width: 600px) and (max-width: 959px) {
  .bkh-warp__card { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); grid-template-rows: 1fr auto; column-gap: 28px; }
  .bkh-warp__pick { grid-row: 1 / 3; }
  .bkh-warp__notes { margin-top: 0; padding-top: 30px; border-top: 0; align-content: start; }
  .bkh-warp__price { align-self: end; }
}
@container bkh-warp (min-width: 960px) {
  .bkh-warp__in {
    grid-template-columns: minmax(0, 1fr) minmax(270px, 310px);
    grid-template-areas: "bar bar" "copy card";
    align-items: end;
    min-height: 640px;
    grid-template-rows: auto 1fr;
  }
  .bkh-warp__veil {
    background:
      linear-gradient(100deg, color-mix(in oklch, var(--bkh-warp-c0) 72%, transparent) 0%, color-mix(in oklch, var(--bkh-warp-c0) 20%, transparent) 52%, transparent 70%),
      linear-gradient(0deg, color-mix(in oklch, var(--bkh-warp-c0) 50%, transparent), transparent 35%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .bkh-warp.is-flat::before { animation: none; }
  .bkh-warp__eyebrow, .bkh-warp__lede, .bkh-warp__cta, .bkh-warp__card,
  .bkh-warp__title span, .bkh-warp__title em, .bkh-warp__row {
    transition: opacity .3s linear; transition-delay: 0ms;
    translate: none; clip-path: none; filter: none;
    @starting-style { opacity: 1; translate: none; clip-path: none; filter: none; }
  }
  .bkh-warp__btn, .bkh-warp__btn svg, .bkh-warp__dot { transition: none; }
}

js:
// Domain-warped fbm (q -> r -> f, after Inigo Quilez) rendered in one fragment shader.
// The palette lives in CSS custom properties; JS parses those oklch() values into sRGB
// uniforms and eases toward them, so a scent change cross-fades the silk itself.
const canvas = root.querySelector(".bkh-warp__gl");
const notesEl = root.querySelector(".bkh-warp__notes");
const priceEl = root.querySelector(".bkh-warp__price b");
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
const uid = Math.random().toString(36).slice(2, 8);
root.querySelectorAll('input[type="radio"]').forEach((i) => { i.name = "bkh-warp-" + uid; });

const SCENTS = {
  ember: { price: "€185", rows: [["Top", "Pink pepper, bitter orange"], ["Heart", "Smoked lapsang, labdanum"], ["Base", "Amber, Atlas cedar, tonka"]] },
  fig:   { price: "€185", rows: [["Top", "Green fig, bergamot"], ["Heart", "Fig leaf, violet leaf"], ["Base", "Vetiver, milky sandalwood"]] },
  iris:  { price: "€215", rows: [["Top", "Aldehydes, carrot seed"], ["Heart", "Orris butter, violet"], ["Base", "Incense, suede, white musk"]] }
};

// oklch(L C H) -> gamma-encoded sRGB, clamped. Enough to feed the shader the CSS palette.
function oklchToRgb(L, C, H) {
  const h = (H * Math.PI) / 180, a = C * Math.cos(h), b = C * Math.sin(h);
  const l = (L + 0.3963377774 * a + 0.2158037573 * b) ** 3;
  const m = (L - 0.1055613458 * a - 0.0638541728 * b) ** 3;
  const s = (L - 0.0894841775 * a - 1.291485548 * b) ** 3;
  const lin = [
    4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
    -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
    -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s
  ];
  return lin.map((x) => {
    x = Math.min(1, Math.max(0, x));
    return x <= 0.0031308 ? 12.92 * x : 1.055 * Math.pow(x, 1 / 2.4) - 0.055;
  });
}
const FALLBACK = [[0.2, 0.05, 0.05], [0.5, 0.15, 0.1], [0.9, 0.6, 0.3], [0.97, 0.93, 0.86]];
function readPalette() {
  const cs = getComputedStyle(root);
  return [0, 1, 2, 3].map((i) => {
    const v = cs.getPropertyValue("--bkh-warp-c" + i);
    const m = /oklch\(\s*([\d.]+)(%?)\s+([\d.]+)\s+([\d.]+)/i.exec(v);
    if (!m) return FALLBACK[i].slice();
    return oklchToRgb(m[2] ? parseFloat(m[1]) / 100 : parseFloat(m[1]), parseFloat(m[3]), parseFloat(m[4]));
  });
}

const VERT = "attribute vec2 p;void main(){gl_Position=vec4(p,0.,1.);}";
const FRAG = [
  "precision highp float;",
  "uniform vec2 uR;uniform float uT;uniform vec2 uM;uniform vec3 uC0,uC1,uC2,uC3;",
  "float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}",
  "float n(vec2 p){vec2 i=floor(p),f=fract(p);vec2 u=f*f*(3.-2.*f);",
  " return mix(mix(h(i),h(i+vec2(1.,0.)),u.x),mix(h(i+vec2(0.,1.)),h(i+vec2(1.,1.)),u.x),u.y);}",
  "float fbm(vec2 p){float v=0.,a=.5;mat2 m=mat2(1.6,1.2,-1.2,1.6);",
  " for(int i=0;i<5;i++){v+=a*n(p);p=m*p;a*=.5;}return v;}",
  "void main(){",
  " vec2 uv=gl_FragCoord.xy/uR;",
  " vec2 p=(gl_FragCoord.xy-.5*uR)/min(uR.x,uR.y)*1.9;",
  " p+=(uM-.5)*vec2(uR.x/uR.y,1.)*.35;",
  " float t=uT*.055;",
  " vec2 q=vec2(fbm(p+vec2(0.,t)),fbm(p+vec2(5.2,1.3)-t));",
  " vec2 r=vec2(fbm(p+3.6*q+vec2(1.7,9.2)+.7*t),fbm(p+3.6*q+vec2(8.3,2.8)-.5*t));",
  " float f=fbm(p+3.6*r);",
  " vec3 c=mix(uC0,uC1,smoothstep(.18,.82,f));",
  " c=mix(c,uC2,smoothstep(.5,1.05,length(q))*.9);",
  " c=mix(c,uC3,smoothstep(.62,1.02,r.x)*.5);",
  " c+=uC3*pow(clamp(f*f*1.55,0.,1.),3.)*.22;",
  " float d=length((uv-uM)*vec2(uR.x/uR.y,1.));",
  " c+=uC2*.14*exp(-d*d*9.);",
  " c=mix(uC0,c,smoothstep(1.45,.25,length(uv-vec2(.62,.48))*1.1));",
  " c+=(h(gl_FragCoord.xy+fract(uT))-.5)/200.;",
  " gl_FragColor=vec4(c,1.);",
  "}"
].join("\n");

let gl = null, prog = null, U = {}, lost = false;
try {
  gl = canvas.getContext("webgl", { antialias: false, alpha: false, depth: false, stencil: false, powerPreference: "low-power" });
} catch (e) { gl = null; }
function compile(type, src) {
  const s = gl.createShader(type);
  gl.shaderSource(s, src); gl.compileShader(s);
  return gl.getShaderParameter(s, gl.COMPILE_STATUS) ? s : null;
}
if (gl) {
  const vs = compile(gl.VERTEX_SHADER, VERT), fs = compile(gl.FRAGMENT_SHADER, FRAG);
  if (vs && fs) {
    prog = gl.createProgram();
    gl.attachShader(prog, vs); gl.attachShader(prog, fs); gl.linkProgram(prog);
    if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) prog = null;
  }
  if (prog) {
    gl.useProgram(prog);
    const buf = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buf);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    const loc = gl.getAttribLocation(prog, "p");
    gl.enableVertexAttribArray(loc);
    gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
    ["uR", "uT", "uM", "uC0", "uC1", "uC2", "uC3"].forEach((k) => { U[k] = gl.getUniformLocation(prog, k); });
  } else {
    const ext = gl.getExtension("WEBGL_lose_context");
    if (ext) ext.loseContext();
    gl = null;
  }
}
if (!gl) root.classList.add("is-flat");
canvas.addEventListener("webglcontextlost", (e) => { e.preventDefault(); lost = true; root.classList.add("is-flat"); });

let cur = readPalette(), tgt = cur.map((c) => c.slice());
const mouse = [0.68, 0.52], aim = [0.68, 0.52];
let t = 9, last = 0, raf = 0, running = false, visible = false, disposed = false;

function draw() {
  if (!gl || lost) return;
  gl.viewport(0, 0, canvas.width, canvas.height);
  gl.uniform2f(U.uR, canvas.width, canvas.height);
  gl.uniform1f(U.uT, t);
  gl.uniform2f(U.uM, mouse[0], mouse[1]);
  gl.uniform3fv(U.uC0, cur[0]); gl.uniform3fv(U.uC1, cur[1]);
  gl.uniform3fv(U.uC2, cur[2]); gl.uniform3fv(U.uC3, cur[3]);
  gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function frame(now) {
  if (!root.isConnected) return dispose();
  if (!visible || document.hidden || lost) { running = false; return; }
  const dt = Math.min(0.05, (now - last) / 1000 || 0.016);
  last = now; t += dt;
  const k = 1 - Math.exp(-dt * 3.2), kc = 1 - Math.exp(-dt * 2.4);
  mouse[0] += (aim[0] - mouse[0]) * k; mouse[1] += (aim[1] - mouse[1]) * k;
  for (let i = 0; i < 4; i++) for (let j = 0; j < 3; j++) cur[i][j] += (tgt[i][j] - cur[i][j]) * kc;
  draw();
  raf = requestAnimationFrame(frame);
}
function start() {
  if (running || disposed || !gl || reduce) return;
  running = true; last = performance.now();
  raf = requestAnimationFrame(frame);
}

// The silk renders at half resolution: it is a soft field, and this keeps a 1440p
// hero at a quarter of the fragment cost. DPR is still honoured, capped at 2.
const ro = new ResizeObserver(() => {
  const dpr = Math.min(2, window.devicePixelRatio || 1) * 0.5;
  const w = Math.max(1, Math.round(canvas.clientWidth * dpr));
  const h = Math.max(1, Math.round(canvas.clientHeight * dpr));
  if (canvas.width !== w || canvas.height !== h) { canvas.width = w; canvas.height = h; }
  if (!running) draw();
});
ro.observe(canvas);

const io = new IntersectionObserver((es) => {
  visible = es[es.length - 1].isIntersecting;
  if (visible) start();
}, { rootMargin: "120px" });
io.observe(root);

const beat = setInterval(() => {
  if (!root.isConnected) return dispose();
}, 1500);

function dispose() {
  if (disposed) return;
  disposed = true; running = false;
  cancelAnimationFrame(raf); clearInterval(beat);
  io.disconnect(); ro.disconnect();
  if (gl) { const ext = gl.getExtension("WEBGL_lose_context"); if (ext) ext.loseContext(); gl = null; }
}

root.addEventListener("pointermove", (e) => {
  if (reduce) return;
  const r = root.getBoundingClientRect();
  aim[0] = (e.clientX - r.left) / r.width;
  aim[1] = 1 - (e.clientY - r.top) / r.height;
});
root.addEventListener("pointerleave", () => { aim[0] = 0.68; aim[1] = 0.52; });

// Scent change: swap the palette on the root, let CSS transition the type colour,
// ease the shader toward the new uniforms, and re-insert the note rows so their
// @starting-style entrance plays again with the --i stagger.
root.querySelector(".bkh-warp__pick").addEventListener("change", (e) => {
  const v = e.target.value;
  if (!SCENTS[v]) return;
  root.dataset.scent = v;
  tgt = readPalette();
  if (reduce || !running) { cur = tgt.map((c) => c.slice()); draw(); }
  const s = SCENTS[v];
  notesEl.replaceChildren(...s.rows.map((row, i) => {
    const d = document.createElement("div");
    d.className = "bkh-warp__row";
    d.style.setProperty("--i", i);
    const dt = document.createElement("dt"); dt.textContent = row[0];
    const dd = document.createElement("dd"); dd.textContent = row[1];
    d.append(dt, dd);
    return d;
  }));
  priceEl.textContent = s.price;
});

