/* Pressline — brutalist kinetic type. Re-theme with --bkh-kinetic-paper / -ink / -signal. */
.bkh-kinetic {
  --bkh-kinetic-paper: oklch(0.955 0.013 95);
  --bkh-kinetic-ink: oklch(0.17 0.012 95);
  --bkh-kinetic-signal: oklch(0.65 0.215 35);
  --bkh-kinetic-rule: 2px solid var(--bkh-kinetic-ink);
  --bkh-kinetic-dim: color-mix(in oklch, var(--bkh-kinetic-ink) 62%, var(--bkh-kinetic-paper));
  --bkh-kinetic-tint: color-mix(in oklch, var(--bkh-kinetic-signal) 14%, var(--bkh-kinetic-paper));
  --bkh-kinetic-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bkh-kinetic-spring: linear(0, 0.009, 0.035 2.1%, 0.141, 0.281 6.7%, 0.723 12.9%, 0.938 16.7%, 1.017, 1.077, 1.121, 1.149 24.3%, 1.159, 1.163, 1.161, 1.154 29.9%, 1.129 32.8%, 1.051 39.6%, 1.017 43.1%, 0.991, 0.977 51%, 0.974 53.8%, 0.975 57.1%, 0.997 69.8%, 1.003 76.9%, 1);
  --bkh-kinetic-snap: cubic-bezier(.2, .9, .1, 1);

  container-type: inline-size;
  container-name: bkh-kinetic;
  position: relative;
  overflow: hidden;
  width: 100%;
  background: var(--bkh-kinetic-paper);
  color: var(--bkh-kinetic-ink);
  border: var(--bkh-kinetic-rule);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  & :where(a) { color: inherit; text-decoration: none; }
  & :focus-visible { outline: 3px solid var(--bkh-kinetic-signal); outline-offset: 3px; }
  & ::selection { background: var(--bkh-kinetic-signal); color: var(--bkh-kinetic-ink); }
}
.bkh-kinetic__in { padding: clamp(14px, 3.4cqi, 40px); padding-bottom: clamp(18px, 3.4cqi, 40px); }

/* ---- bar ---- */
.bkh-kinetic__bar {
  display: flex; align-items: center; gap: 20px;
  padding-bottom: 14px; border-bottom: var(--bkh-kinetic-rule);
}
.bkh-kinetic__logo {
  display: inline-flex; align-items: center; gap: 9px;
  font-weight: 900; font-size: 15px; letter-spacing: .08em;
  & svg { width: 24px; height: 24px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: square; }
}
.bkh-kinetic__nav {
  display: none; gap: 2px; margin-inline-start: 12px;
  & a { padding: 6px 10px; font: 600 12px/1 var(--bkh-kinetic-mono); text-transform: uppercase; letter-spacing: .06em; }
  & a:hover { background: var(--bkh-kinetic-ink); color: var(--bkh-kinetic-paper); }
}
.bkh-kinetic__mini {
  margin-inline-start: auto;
  padding: 9px 14px; border: var(--bkh-kinetic-rule);
  font: 700 12px/1 var(--bkh-kinetic-mono); text-transform: uppercase; letter-spacing: .06em;
  box-shadow: 3px 3px 0 var(--bkh-kinetic-ink);
  transition: translate .15s var(--bkh-kinetic-snap), box-shadow .15s var(--bkh-kinetic-snap), background .15s;
  &:hover { background: var(--bkh-kinetic-signal); translate: -2px -2px; box-shadow: 5px 5px 0 var(--bkh-kinetic-ink); }
  &:active { translate: 3px 3px; box-shadow: 0 0 0 var(--bkh-kinetic-ink); }
}

/* ---- meta row ---- */
.bkh-kinetic__meta {
  display: flex; flex-wrap: wrap; gap: 6px 18px;
  padding: 10px 0; border-bottom: var(--bkh-kinetic-rule);
  font: 500 11.5px/1.4 var(--bkh-kinetic-mono); text-transform: uppercase; letter-spacing: .04em;
  & > span:nth-child(2) { display: none; }
}
.bkh-kinetic__live {
  margin-inline-start: auto; display: inline-flex; align-items: center; gap: 8px;
  & i { width: 9px; height: 9px; background: var(--bkh-kinetic-signal); animation: bkh-kinetic-blink 1.1s steps(2, jump-none) infinite; }
  & b { font-weight: 700; font-variant-numeric: tabular-nums; }
}
@keyframes bkh-kinetic-blink { 50% { opacity: .15; } }

/* ---- the headline ---- */
.bkh-kinetic__title {
  margin: clamp(18px, 3.5cqi, 36px) 0 clamp(18px, 3.5cqi, 34px);
  font-weight: 900;
  font-size: clamp(2.2rem, 12.4cqi, 11rem);
  line-height: .86;
  letter-spacing: -.045em;
  text-transform: uppercase;
}
.bkh-kinetic__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.bkh-kinetic__line { display: block; white-space: nowrap; }
.bkh-kinetic__line + .bkh-kinetic__line { margin-top: .04em; }
.bkh-kinetic__ch {
  display: inline-block;
  scale: 1 var(--s, 1);
  transform-origin: 50% 92%;
  transition: scale .55s var(--bkh-kinetic-spring);
}
.bkh-kinetic__slab {
  display: inline-block;
  padding: .02em .14em .06em .1em;
  margin-inline-start: -.04em;
  background: var(--bkh-kinetic-signal);
  box-shadow: .06em .06em 0 var(--bkh-kinetic-ink);
  overflow: clip;
  transition: width .5s var(--bkh-kinetic-snap);
}
.bkh-kinetic__word {
  display: inline-block; perspective: 7em;
  & .bkh-kinetic__ch { animation: bkh-kinetic-in .9s var(--bkh-kinetic-spring) both; animation-delay: calc(var(--i) * 38ms); }
  &.is-out .bkh-kinetic__ch { animation: bkh-kinetic-out .3s cubic-bezier(.6, 0, .9, .3) both; animation-delay: calc(var(--i) * 26ms); }
}
@keyframes bkh-kinetic-in {
  from { transform: translateY(70%) rotateX(-95deg); opacity: 0; }
  to { transform: none; opacity: 1; }
}
@keyframes bkh-kinetic-out {
  from { transform: none; opacity: 1; }
  to { transform: translateY(-70%) rotateX(95deg); opacity: 0; }
}

/* ---- foot: lede, stats, actions on a ruled grid ---- */
.bkh-kinetic__foot {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "lede" "stats" "actions";
  border-top: var(--bkh-kinetic-rule);
}
.bkh-kinetic__lede {
  grid-area: lede; margin: 0; padding: 16px 0;
  font-size: clamp(15px, 13px + .5cqi, 18px); line-height: 1.5; font-weight: 500;
  text-wrap: pretty; max-width: 52ch;
}
.bkh-kinetic__stats {
  grid-area: stats; margin: 0;
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr));
  border-top: var(--bkh-kinetic-rule); border-left: var(--bkh-kinetic-rule);
  & div { padding: 12px 12px 10px; border-right: var(--bkh-kinetic-rule); border-bottom: var(--bkh-kinetic-rule); transition: background .2s; }
  & div:hover { background: var(--bkh-kinetic-tint); }
  & dt { font: 600 10.5px/1.2 var(--bkh-kinetic-mono); text-transform: uppercase; letter-spacing: .06em; color: var(--bkh-kinetic-dim); }
  & dd { margin: 6px 0 0; font-size: clamp(28px, 22px + 2cqi, 44px); font-weight: 900; letter-spacing: -.04em; line-height: 1; font-variant-numeric: tabular-nums; }
  & small { font-size: .5em; font-weight: 800; letter-spacing: 0; margin-inline-start: 2px; }
}
.bkh-kinetic__actions {
  grid-area: actions; padding-top: 16px;
  display: flex; flex-wrap: wrap; gap: 12px; align-items: stretch;
}
.bkh-kinetic__btn {
  flex: 1 1 auto;
  display: inline-flex; align-items: center; justify-content: space-between; gap: 18px;
  padding: 15px 18px;
  background: var(--bkh-kinetic-ink); color: var(--bkh-kinetic-paper);
  border: var(--bkh-kinetic-rule);
  font-weight: 800; font-size: 15px; letter-spacing: -.01em;
  box-shadow: 5px 5px 0 var(--bkh-kinetic-signal);
  transition: translate .15s var(--bkh-kinetic-snap), box-shadow .15s var(--bkh-kinetic-snap);
  & svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: square; transition: translate .25s var(--bkh-kinetic-snap); }
  &:hover { translate: -2px -2px; box-shadow: 7px 7px 0 var(--bkh-kinetic-signal); }
  &:hover svg { translate: 4px 0; }
  &:active { translate: 5px 5px; box-shadow: 0 0 0 var(--bkh-kinetic-signal); }
}
.bkh-kinetic__btn--ghost {
  background: var(--bkh-kinetic-paper); color: var(--bkh-kinetic-ink);
  box-shadow: 5px 5px 0 var(--bkh-kinetic-ink);
  &:hover { box-shadow: 7px 7px 0 var(--bkh-kinetic-ink); background: var(--bkh-kinetic-tint); }
  &:active { box-shadow: 0 0 0 var(--bkh-kinetic-ink); }
}
.bkh-kinetic__pause {
  flex: 0 0 auto; width: 52px;
  display: grid; place-items: center;
  background: var(--bkh-kinetic-paper); color: var(--bkh-kinetic-ink);
  border: var(--bkh-kinetic-rule); cursor: pointer; padding: 0;
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 3; stroke-linecap: square; stroke-linejoin: miter; grid-area: 1 / 1; }
  & .bkh-kinetic__i-play { display: none; fill: currentColor; stroke-width: 2; }
  &[aria-pressed="true"] { background: var(--bkh-kinetic-signal); }
  &[aria-pressed="true"] .bkh-kinetic__i-play { display: block; }
  &[aria-pressed="true"] .bkh-kinetic__i-pause { display: none; }
  &:hover { background: var(--bkh-kinetic-tint); }
}

/* ---- marquee band ---- */
.bkh-kinetic__band {
  border-top: var(--bkh-kinetic-rule);
  background: var(--bkh-kinetic-ink); color: var(--bkh-kinetic-paper);
  overflow: hidden; padding: 12px 0;
}
.bkh-kinetic__track {
  display: flex; align-items: center; gap: 22px; width: max-content;
  padding-inline-end: 22px;
  font-weight: 900; font-size: clamp(18px, 14px + 1.4cqi, 28px); text-transform: uppercase; letter-spacing: -.02em;
  animation: bkh-kinetic-marquee 26s linear infinite;
  & svg { width: .8em; height: .8em; fill: none; stroke: var(--bkh-kinetic-signal); stroke-width: 3.2; stroke-linecap: square; flex: none; }
}
@keyframes bkh-kinetic-marquee { to { transform: translateX(-50%); } }
.bkh-kinetic:has(.bkh-kinetic__pause[aria-pressed="true"]) {
  & .bkh-kinetic__track, & .bkh-kinetic__live i { animation-play-state: paused; }
}
.bkh-kinetic__band:hover .bkh-kinetic__track { animation-play-state: paused; }

@container bkh-kinetic (min-width: 620px) {
  .bkh-kinetic__nav { display: flex; }
  .bkh-kinetic__meta > span:nth-child(2) { display: inline; }
  .bkh-kinetic__stats { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .bkh-kinetic__btn { flex: 0 1 auto; }
}
@container bkh-kinetic (min-width: 900px) {
  .bkh-kinetic__foot {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr);
    grid-template-areas: "lede stats" "actions stats";
    column-gap: 28px;
  }
  .bkh-kinetic__lede { padding-top: 18px; }
  .bkh-kinetic__stats { grid-template-columns: repeat(2, minmax(0, 1fr)); border-top: 0; align-self: start; }
  .bkh-kinetic__actions { align-self: end; padding-bottom: 4px; }
}

@media (prefers-reduced-motion: reduce) {
  .bkh-kinetic__ch { transition: none; scale: none; }
  .bkh-kinetic__word .bkh-kinetic__ch, .bkh-kinetic__word.is-out .bkh-kinetic__ch { animation: none; }
  .bkh-kinetic__slab { transition: none; }
  .bkh-kinetic__track { animation: none; flex-wrap: wrap; width: auto; padding-inline: 16px; }
  .bkh-kinetic__track > :nth-child(n + 11) { display: none; }
  .bkh-kinetic__live i { animation: none; }
  .bkh-kinetic__btn, .bkh-kinetic__mini, .bkh-kinetic__btn svg { transition: none; }
}

