// Kinetic headline: one verb flips letter by letter (rotateX + spring linear()),
// the slab FLIPs its width to the new word, and the static lines stretch toward the
// pointer. Letter centres are measured once per resize, never inside pointermove.
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
const WORDS = ["COMPILED", "TESTED", "CACHED", "SHIPPED"];
const wordEl = root.querySelector(".bkh-kinetic__word");
const slab = root.querySelector(".bkh-kinetic__slab");
const pauseBtn = root.querySelector(".bkh-kinetic__pause");
const countEl = root.querySelector(".bkh-kinetic__count");

function split(el, text) {
  el.replaceChildren(...Array.from(text, (ch, i) => {
    const s = document.createElement("span");
    s.className = "bkh-kinetic__ch";
    s.style.setProperty("--i", i);
    s.textContent = ch === " " ? " " : ch;
    return s;
  }));
}
root.querySelectorAll(".bkh-kinetic__split").forEach((el) => split(el, el.textContent.trim()));
split(wordEl, wordEl.textContent.trim());

let chars = [], centers = [];
function measure() {
  chars = Array.from(root.querySelectorAll(".bkh-kinetic__split .bkh-kinetic__ch"));
  const rr = root.getBoundingClientRect();
  centers = chars.map((c) => {
    const r = c.getBoundingClientRect();
    return [r.left - rr.left + r.width / 2, r.top - rr.top + r.height / 2];
  });
}
const ro = new ResizeObserver(() => measure());
ro.observe(root);

// ---- pointer stretch, batched to one write pass per frame ----
let px = -1e5, py = -1e5, queued = false;
function stretch() {
  if (!root.isConnected) return;
  queued = false;
  for (let i = 0; i < chars.length; i++) {
    const dx = (px - centers[i][0]) / 150, dy = (py - centers[i][1]) / 190;
    const s = 1 + 0.4 * Math.exp(-(dx * dx + dy * dy));
    chars[i].style.setProperty("--s", s.toFixed(3));
  }
}
function queue() { if (!queued) { queued = true; requestAnimationFrame(stretch); } }
if (!reduce) {
  root.addEventListener("pointermove", (e) => {
    if (e.pointerType === "touch") return;
    const r = root.getBoundingClientRect();
    px = e.clientX - r.left; py = e.clientY - r.top;
    queue();
  });
  root.addEventListener("pointerleave", () => { px = py = -1e5; queue(); });
}

// ---- word cycle ----
let idx = WORDS.length - 1, paused = false, visible = false, timer = 0, swapping = false, disposed = false;
function swap(word) {
  swapping = true;
  const w0 = slab.getBoundingClientRect().width;
  wordEl.classList.add("is-out");
  const outMs = 300 + wordEl.children.length * 26;
  setTimeout(() => {
    if (!root.isConnected) return dispose();
    wordEl.classList.remove("is-out");
    split(wordEl, word);
    // FLIP the slab width: content changes do not trigger transitions on their own.
    slab.style.width = "auto";
    const w1 = slab.getBoundingClientRect().width;
    slab.style.width = w0 + "px";
    slab.getBoundingClientRect();
    slab.style.width = w1 + "px";
    setTimeout(() => { if (root.isConnected) slab.style.width = ""; swapping = false; }, 560);
  }, outMs);
}
function tick() {
  if (!root.isConnected) return dispose();
  timer = 0;
  if (swapping) return schedule();
  if (paused || !visible || document.hidden) return;
  idx = (idx + 1) % WORDS.length;
  swap(WORDS[idx]);
  schedule();
}
function schedule() {
  if (reduce || paused || timer) return;
  timer = setTimeout(tick, 2600);
}

// ---- live build counter: a bounded random walk ----
let builds = 3912;
const counter = setInterval(() => {
  if (!root.isConnected) return dispose();
  if (paused || !visible || document.hidden || reduce) return;
  builds = Math.max(3600, Math.min(4300, builds + Math.round((Math.random() - 0.45) * 60)));
  countEl.textContent = builds.toLocaleString("en-US");
}, 1400);

const io = new IntersectionObserver((es) => {
  visible = es[es.length - 1].isIntersecting;
  if (visible) { measure(); schedule(); }
}, { threshold: 0.15 });
io.observe(root);

pauseBtn.addEventListener("click", () => {
  paused = !paused;
  pauseBtn.setAttribute("aria-pressed", String(paused));
  pauseBtn.setAttribute("aria-label", paused ? "Play animation" : "Pause animation");
  if (paused) { clearTimeout(timer); timer = 0; } else schedule();
});

function dispose() {
  if (disposed) return;
  disposed = true;
  clearTimeout(timer); clearInterval(counter);
  io.disconnect(); ro.disconnect();
}

