/* Plumtree — a CSS-3D phone with a live app on its screen.
   Re-theme: --bkh-device-bg, -ink, -plum (partner A), -sage (partner B). */
.bkh-device {
  --bkh-device-bg: oklch(0.972 0.012 85);
  --bkh-device-ink: oklch(0.25 0.035 350);
  --bkh-device-plum: oklch(0.50 0.16 352);
  --bkh-device-sage: oklch(0.70 0.08 150);
  --bkh-device-card: color-mix(in oklch, var(--bkh-device-bg), white 75%);
  --bkh-device-line: color-mix(in oklch, var(--bkh-device-ink) 12%, var(--bkh-device-bg));
  --bkh-device-mute: color-mix(in oklch, var(--bkh-device-ink) 62%, var(--bkh-device-bg));
  --bkh-device-ease: cubic-bezier(.22, 1, .36, 1);
  --bkh-device-rx: 9deg; --bkh-device-ry: -20deg; --bkh-device-rz: 2deg; --bkh-device-gx: 40%;

  container-type: inline-size;
  container-name: bkh-device;
  position: relative;
  overflow: hidden;
  width: 100%;
  border-radius: 24px;
  background:
    radial-gradient(60% 55% at 78% 58%, color-mix(in oklch, var(--bkh-device-plum) 12%, transparent), transparent 70%),
    radial-gradient(40% 40% at 92% 12%, color-mix(in oklch, var(--bkh-device-sage) 22%, transparent), transparent 70%),
    var(--bkh-device-bg);
  color: var(--bkh-device-ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  & :where(a) { color: inherit; text-decoration: none; }
  & :focus-visible { outline: 2px solid var(--bkh-device-plum); outline-offset: 3px; border-radius: 10px; }
}
.bkh-device__in {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "bar" "copy" "tabs" "stage";
  gap: 28px;
  padding: clamp(18px, 4.4cqi, 52px);
}

/* ---- bar ---- */
.bkh-device__bar { grid-area: bar; display: flex; align-items: center; gap: 24px; font-size: 14px; }
.bkh-device__logo {
  display: inline-flex; align-items: center; gap: 8px; font-weight: 700; font-size: 17px; letter-spacing: -.02em;
  & svg { width: 26px; height: 26px; fill: none; stroke: var(--bkh-device-plum); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
}
.bkh-device__nav {
  display: none; gap: 22px; margin-inline: auto; color: var(--bkh-device-mute);
  & a:hover { color: var(--bkh-device-ink); }
}
.bkh-device__login { margin-inline-start: auto; font-weight: 600; padding: 8px 14px; border-radius: 999px; border: 1px solid var(--bkh-device-line); transition: background .25s; }
.bkh-device__login:hover { background: var(--bkh-device-card); }

/* ---- copy ---- */
.bkh-device__copy { grid-area: copy; }
.bkh-device__eyebrow {
  margin: 0 0 18px; display: inline-flex; align-items: center; gap: 10px;
  padding: 5px 12px 5px 5px; border-radius: 999px; background: var(--bkh-device-card); border: 1px solid var(--bkh-device-line);
  font-size: 13px; font-weight: 500;
  & span { padding: 3px 9px; border-radius: 999px; background: var(--bkh-device-plum); color: var(--bkh-device-bg); font-size: 11.5px; font-weight: 700; letter-spacing: .02em; }
}
.bkh-device__title {
  margin: 0; max-width: 13ch;
  font-size: clamp(2.3rem, 1rem + 5.6cqi, 4.6rem);
  line-height: 1; letter-spacing: -.045em; font-weight: 750;
  text-wrap: balance;
}
.bkh-device__lede { margin: 20px 0 0; max-width: 42ch; font-size: clamp(15px, 13.5px + .4cqi, 18px); line-height: 1.55; color: var(--bkh-device-mute); text-wrap: pretty; }
.bkh-device__cta { margin-top: 28px; display: flex; flex-wrap: wrap; align-items: center; gap: 12px 22px; }
.bkh-device__btn {
  padding: 14px 22px; border-radius: 999px;
  background: var(--bkh-device-ink); color: var(--bkh-device-bg);
  font-weight: 650; font-size: 15px;
  box-shadow: 0 1px 0 color-mix(in oklch, white 30%, transparent) inset, 0 10px 24px -10px color-mix(in oklch, var(--bkh-device-plum) 70%, transparent);
  transition: background .3s var(--bkh-device-ease), translate .3s var(--bkh-device-ease), box-shadow .3s;
  &:hover { background: var(--bkh-device-plum); translate: 0 -1px; }
  &:active { translate: 0 1px; }
}
.bkh-device__ghost {
  display: inline-flex; align-items: center; gap: 8px; font-weight: 600; font-size: 15px;
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; transition: translate .3s var(--bkh-device-ease); }
  &:hover svg { translate: 3px 0; }
}

/* ---- tabs (the pill is one element that moves between tabs) ---- */
.bkh-device__tabs { grid-area: tabs; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; padding: 5px; border-radius: 18px; background: color-mix(in oklch, var(--bkh-device-ink) 5%, transparent); }
.bkh-device__tab {
  position: relative; isolation: isolate;
  appearance: none; border: 0; background: none; color: inherit; font: inherit; text-align: start; cursor: pointer;
  display: grid; grid-template-columns: auto 1fr; align-items: center; gap: 2px 10px;
  padding: 11px 12px; border-radius: 13px;
  & svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; color: var(--bkh-device-mute); transition: color .3s; }
  & b { font-size: 14.5px; font-weight: 650; }
  & > span:not(.bkh-device__pill) { display: none; grid-column: 2; font-size: 13px; color: var(--bkh-device-mute); }
  &:hover svg { color: var(--bkh-device-ink); }
  &[aria-selected="true"] svg { color: var(--bkh-device-plum); }
  &:focus-visible { outline-offset: 0; }
}
.bkh-device__pill {
  position: absolute; inset: 0; z-index: -1; border-radius: inherit;
  background: var(--bkh-device-card);
  box-shadow: 0 1px 2px color-mix(in oklch, var(--bkh-device-ink) 12%, transparent), 0 8px 20px -12px color-mix(in oklch, var(--bkh-device-ink) 40%, transparent);
}

/* ---- the phone ---- */
.bkh-device__stage {
  grid-area: stage; position: relative;
  display: grid; place-items: center;
  padding-block: 18px 34px;
  perspective: 1300px;
  outline: none;
}
.bkh-device__phone {
  --r: 15%;
  position: relative;
  width: clamp(220px, 24cqi, 272px);
  aspect-ratio: 9 / 19;
  transform-style: preserve-3d;
  transform: rotateX(var(--bkh-device-rx)) rotateY(var(--bkh-device-ry)) rotateZ(var(--bkh-device-rz));
}
.bkh-device__layer, .bkh-device__front { position: absolute; inset: 0; border-radius: var(--r) / calc(var(--r) * 9 / 19); }
.bkh-device__layer {
  transform: translateZ(calc(var(--z) * -1.7px));
  background: linear-gradient(115deg, color-mix(in oklch, var(--bkh-device-plum) 55%, black), color-mix(in oklch, var(--bkh-device-plum) 80%, white) 45%, color-mix(in oklch, var(--bkh-device-plum) 50%, black));
}
.bkh-device__layer--back { background: color-mix(in oklch, var(--bkh-device-plum) 45%, black); }
.bkh-device__front {
  container-type: inline-size;
  padding: 3.2%;
  background: oklch(0.17 0.012 350);
