}
.bkh-device__avs { display: inline-flex; & i { display: grid; place-items: center; width: 8.5cqi; height: 8.5cqi; border-radius: 50%; font-style: normal; font-size: 3.6cqi; font-weight: 700; color: white; border: .6cqi solid color-mix(in oklch, var(--bkh-device-bg), white 55%); }
