// A CSS-3D phone driven by a damped spring toward the pointer, with tabs that swap
// the live screen inside document.startViewTransition. The active-tab pill is one
// element moved between tabs, so the transition morphs it; its timing is re-tuned
// through the Web Animations API because ::view-transition-* cannot be scoped in CSS.
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
const uid = Math.random().toString(36).slice(2, 8);
const tabs = Array.from(root.querySelectorAll(".bkh-device__tab"));
const views = Array.from(root.querySelectorAll(".bkh-device__view"));
const panel = root.querySelector(".bkh-device__stage");
const pill = root.querySelector(".bkh-device__pill");
const phone = root.querySelector(".bkh-device__phone");
const shadow = root.querySelector(".bkh-device__shadow");
const faT = root.querySelector(".bkh-device__fa-t");
const faS = root.querySelector(".bkh-device__fa-s");
const fb = root.querySelector(".bkh-device__fb");
const num = root.querySelector(".bkh-device__num");

const FLOATS = {
  split: ["Corner Grocer · £42.80", "Maya £22.26 · Theo £20.54", "52 / 48 by income"],
  save: ["Theo added £50.00", "Lisbon, May · 65% saved", "Earning 4.1% AER"],
  plan: ["Rent scheduled · 1 Oct", "Maya £598.00 · Theo £552.00", "4 bills · £1,283.39"]
};

panel.id = "bkh-device-panel-" + uid;
tabs.forEach((t, i) => {
  t.id = "bkh-device-tab-" + uid + "-" + i;
  t.setAttribute("aria-controls", panel.id);
});
panel.setAttribute("aria-labelledby", tabs[0].id);

let cur = 0;
function apply(i) {
  tabs.forEach((t, j) => {
    t.setAttribute("aria-selected", String(j === i));
    t.tabIndex = j === i ? 0 : -1;
  });
  tabs[i].prepend(pill);
  const name = tabs[i].dataset.view;
  views.forEach((v) => { v.hidden = v.dataset.view !== name; });
  root.dataset.view = name;
  panel.setAttribute("aria-labelledby", tabs[i].id);
  const f = FLOATS[name];
  faT.textContent = f[0]; faS.textContent = f[1]; fb.textContent = f[2];
}
function select(i) {
  if (i === cur) return;
  cur = i;
  if (!reduce && typeof document.startViewTransition === "function") {
    const name = "bkh-device-pill-" + uid;
    pill.style.viewTransitionName = name;
    let vt;
    try { vt = document.startViewTransition(() => apply(i)); }
    catch (e) { pill.style.viewTransitionName = ""; apply(i); return; }
    vt.ready.then(() => {
      document.getAnimations().forEach((a) => {
        const pe = a.effect && a.effect.pseudoElement;
        if (pe && pe.indexOf(name) > -1) a.effect.updateTiming({ duration: 560, easing: "cubic-bezier(.22, 1, .36, 1)" });
      });
    }).catch(() => {});
    const clear = () => { pill.style.viewTransitionName = ""; };
    vt.finished.then(clear, clear);
  } else {
    // Fallback: FLIP the pill by hand.
    const r0 = pill.getBoundingClientRect();
    apply(i);
    if (reduce || !pill.animate) return;
    const r1 = pill.getBoundingClientRect();
    if (!r1.width || !r1.height) return;
    pill.animate([
      { transformOrigin: "0 0", transform: "translate(" + (r0.left - r1.left) + "px," + (r0.top - r1.top) + "px) scale(" + r0.width / r1.width + "," + r0.height / r1.height + ")" },
      { transformOrigin: "0 0", transform: "none" }
    ], { duration: 520, easing: "cubic-bezier(.22, 1, .36, 1)" });
  }
}
tabs.forEach((t, i) => t.addEventListener("click", () => select(i)));
root.querySelector(".bkh-device__tabs").addEventListener("keydown", (e) => {
  let i = cur;
  if (e.key === "ArrowRight" || e.key === "ArrowDown") i = (cur + 1) % tabs.length;
  else if (e.key === "ArrowLeft" || e.key === "ArrowUp") i = (cur - 1 + tabs.length) % tabs.length;
  else if (e.key === "Home") i = 0;
  else if (e.key === "End") i = tabs.length - 1;
  else return;
  e.preventDefault();
  select(i);
  tabs[i].focus();
});

// ---- tilt: critically-damped-ish spring toward the pointer, idle sway at rest ----
const REST = { rx: 9, ry: -20 };
const aim = { rx: REST.rx, ry: REST.ry };
const st = { rx: REST.rx, ry: REST.ry, vx: 0, vy: 0 };
let hover = false, visible = false, running = false, disposed = false, raf = 0, last = 0, t = 0, counted = false;

function frame(now) {
  if (!root.isConnected) return dispose();
  if (!visible || document.hidden) { running = false; return; }
  const dt = Math.min(0.033, (now - last) / 1000 || 0.016);
  last = now; t += dt;
  const sway = hover ? 0 : 1;
  const tx = aim.rx + Math.sin(t * 0.8) * 2.2 * sway;
  const ty = aim.ry + Math.sin(t * 0.55 + 1) * 5 * sway;
  const K = 64, C = 13;
  st.vx += ((tx - st.rx) * K - st.vx * C) * dt; st.rx += st.vx * dt;
  st.vy += ((ty - st.ry) * K - st.vy * C) * dt; st.ry += st.vy * dt;
  const off = st.ry - REST.ry;
  phone.style.setProperty("--bkh-device-rx", st.rx.toFixed(2) + "deg");
  phone.style.setProperty("--bkh-device-ry", st.ry.toFixed(2) + "deg");
  phone.style.setProperty("--bkh-device-rz", (2 - off * 0.06).toFixed(2) + "deg");
  phone.style.setProperty("--bkh-device-gx", (40 + off * 2.4).toFixed(1) + "%");
  shadow.style.setProperty("--bkh-device-sh", (-off * 1.6).toFixed(1));
  raf = requestAnimationFrame(frame);
}
function start() {
  if (running || disposed || reduce) return;
  running = true; last = performance.now();
  raf = requestAnimationFrame(frame);
}
root.addEventListener("pointermove", (e) => {
  if (reduce || e.pointerType === "touch") return;
  const r = root.getBoundingClientRect();
  const nx = Math.max(-1, Math.min(1, ((e.clientX - r.left) / r.width - 0.62) * 2.2));
  const ny = Math.max(-1, Math.min(1, ((e.clientY - r.top) / r.height - 0.5) * 2));
  aim.ry = REST.ry + nx * 24;
  aim.rx = REST.rx - ny * 11;
  hover = true;
});
root.addEventListener("pointerleave", () => { aim.rx = REST.rx; aim.ry = REST.ry; hover = false; });

function countUp() {
  counted = true;
  if (reduce) return;
  const target = 3248.6, t0 = performance.now();
  const fmt = new Intl.NumberFormat("en-GB", { style: "currency", currency: "GBP" });
  function step(now) {
    if (!root.isConnected) return;
    const p = Math.min(1, (now - t0) / 1500);
    num.textContent = fmt.format(target * (1 - Math.pow(1 - p, 4)));
    if (p < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

const io = new IntersectionObserver((es) => {
  visible = es[es.length - 1].isIntersecting;
  if (visible) { start(); if (!counted) countUp(); }
}, { threshold: 0.2 });
io.observe(root);
const beat = setInterval(() => {
  if (!root.isConnected) return dispose();
}, 1500);
function dispose() {
  if (disposed) return;
  disposed = true; running = false;
  cancelAnimationFrame(raf); clearInterval(beat); io.disconnect();
}

