/* Sortwell — a headline drawn by ~2,400 particles. Re-theme with --bkh-particles-bg / -ink / -hot.
   The canvas reads the same variables, so particle colours follow the theme. */
.bkh-particles {
  --bkh-particles-bg: oklch(0.165 0.012 125);
  --bkh-particles-ink: oklch(0.95 0.012 110);
  --bkh-particles-hot: oklch(0.91 0.19 120);
  --bkh-particles-mute: color-mix(in oklch, var(--bkh-particles-ink) 58%, var(--bkh-particles-bg));
  --bkh-particles-line: color-mix(in oklch, var(--bkh-particles-ink) 13%, transparent);
  --bkh-particles-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bkh-particles-ease: cubic-bezier(.16, 1, .3, 1);

  container-type: inline-size;
  container-name: bkh-particles;
  position: relative; isolation: isolate; overflow: hidden;
  width: 100%;
  border-radius: 14px;
  background: var(--bkh-particles-bg);
  color: var(--bkh-particles-ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  touch-action: pan-y;

  & :where(a) { color: inherit; text-decoration: none; }
  & :focus-visible { outline: 2px solid var(--bkh-particles-hot); outline-offset: 3px; border-radius: 6px; }
}
.bkh-particles__cv { position: absolute; inset: 0; width: 100%; height: 100%; display: block; z-index: 0; }
.bkh-particles__in { position: relative; z-index: 1; padding: clamp(16px, 4cqi, 48px); }

.bkh-particles__bar { display: flex; align-items: center; gap: 22px; font-size: 13.5px; }
.bkh-particles__logo {
  display: inline-flex; align-items: center; gap: 8px; font-family: var(--bkh-particles-mono); font-weight: 700; font-size: 15px; letter-spacing: -.02em;
  & svg { width: 22px; height: 22px; fill: none; stroke: var(--bkh-particles-hot); stroke-width: 2; stroke-linecap: round; }
  & circle { fill: var(--bkh-particles-hot); stroke: none; }
}
.bkh-particles__nav { display: none; gap: 22px; color: var(--bkh-particles-mute); & a:hover { color: var(--bkh-particles-ink); } }
.bkh-particles__key {
  margin-inline-start: auto; padding: 8px 13px; border-radius: 8px;
  border: 1px solid var(--bkh-particles-line); font-family: var(--bkh-particles-mono); font-size: 12px;
  transition: border-color .25s, background .25s;
  &:hover { border-color: var(--bkh-particles-hot); background: color-mix(in oklch, var(--bkh-particles-hot) 10%, transparent); }
}

/* the reserved band the particles assemble into */
.bkh-particles__field {
  position: relative;
  height: clamp(150px, 25cqi, 290px);
  margin: clamp(16px, 3cqi, 30px) 0 clamp(14px, 2.6cqi, 28px);
  border-block: 1px dashed var(--bkh-particles-line);
  background: linear-gradient(var(--bkh-particles-line), var(--bkh-particles-line)) 0 50% / 100% 1px no-repeat;
}
.bkh-particles__tick {
  position: absolute; font: 500 10.5px/1 var(--bkh-particles-mono); letter-spacing: .02em; color: var(--bkh-particles-mute);
  padding: 7px 0; font-variant-numeric: tabular-nums;
  & b { color: var(--bkh-particles-hot); font-weight: 600; }
}
.bkh-particles__tick--tl { top: 0; left: 0; }
.bkh-particles__tick--tr { top: 0; right: 0; }
.bkh-particles__tick--bl { bottom: 0; left: 0; }
.bkh-particles__tick--br { bottom: 0; right: 0; display: none; }
.bkh-particles__fallback {
  display: none; position: absolute; inset: 0; place-items: center;
  font-weight: 800; font-size: clamp(64px, 18cqi, 220px); letter-spacing: -.05em; color: var(--bkh-particles-hot);
}
.bkh-particles.is-flat .bkh-particles__fallback { display: grid; }

.bkh-particles__copy { display: grid; grid-template-columns: minmax(0, 1fr); gap: 30px; }
.bkh-particles__eyebrow {
  margin: 0 0 14px; display: inline-flex; align-items: center; gap: 9px;
  font: 500 12px/1 var(--bkh-particles-mono); color: var(--bkh-particles-mute); letter-spacing: .02em;
  & span { width: 7px; height: 7px; border-radius: 50%; background: var(--bkh-particles-hot); box-shadow: 0 0 0 4px color-mix(in oklch, var(--bkh-particles-hot) 18%, transparent); }
}
.bkh-particles__title {
  margin: 0; max-width: 18ch;
  font-size: clamp(1.9rem, 1rem + 3.4cqi, 3.5rem); font-weight: 700; line-height: 1.04; letter-spacing: -.035em;
  text-wrap: balance;
}
.bkh-particles__lede { margin: 16px 0 0; max-width: 50ch; color: var(--bkh-particles-mute); font-size: clamp(15px, 13.5px + .35cqi, 17px); line-height: 1.6; text-wrap: pretty; }
.bkh-particles__cta { margin-top: 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 12px 22px; }
.bkh-particles__btn {
  padding: 13px 18px; border-radius: 10px;
  background: var(--bkh-particles-hot); color: var(--bkh-particles-bg);
  font-weight: 700; font-size: 14.5px;
  transition: translate .3s var(--bkh-particles-ease), box-shadow .3s var(--bkh-particles-ease);
  &:hover { translate: 0 -2px; box-shadow: 0 10px 30px -8px color-mix(in oklch, var(--bkh-particles-hot) 60%, transparent); }
  &:active { translate: 0 0; }
}
.bkh-particles__link {
  display: inline-flex; align-items: center; gap: 6px; font-weight: 600; font-size: 14.5px;
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; transition: translate .3s var(--bkh-particles-ease); }
  &:hover svg { translate: 2px -2px; }
}

.bkh-particles__try { margin: 0; }
.bkh-particles__lbl { display: block; margin-bottom: 8px; font: 600 11px/1 var(--bkh-particles-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--bkh-particles-mute); }
.bkh-particles__box {
  display: flex; align-items: center; gap: 10px;
  padding: 4px 6px 4px 12px; border-radius: 12px;
  background: color-mix(in oklch, var(--bkh-particles-bg), var(--bkh-particles-ink) 6%);
  border: 1px solid var(--bkh-particles-line);
  transition: border-color .25s, box-shadow .25s;
  & svg { width: 18px; height: 18px; flex: none; fill: none; stroke: var(--bkh-particles-mute); stroke-width: 2; stroke-linecap: round; }
  & kbd { font: 600 10.5px/1 var(--bkh-particles-mono); padding: 6px 7px; border-radius: 6px; border: 1px solid var(--bkh-particles-line); color: var(--bkh-particles-mute); }
  &:has(input:focus-visible) { border-color: var(--bkh-particles-hot); box-shadow: 0 0 0 4px color-mix(in oklch, var(--bkh-particles-hot) 16%, transparent); }
}
.bkh-particles__input {
  flex: 1; min-width: 0; padding: 11px 0; border: 0; outline: 0; background: none; color: var(--bkh-particles-ink);
  font: 500 16px/1.2 var(--bkh-particles-mono); caret-color: var(--bkh-particles-hot);
  &::placeholder { color: var(--bkh-particles-mute); opacity: .8; }
  &:focus-visible { outline: none; }
}
.bkh-particles__hint { margin: 9px 0 0; font-size: 12.5px; line-height: 1.5; color: var(--bkh-particles-mute); text-wrap: pretty; }
.bkh-particles__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; margin: 0; }
.bkh-particles__stats {
  margin: 24px 0 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr));
  border-top: 1px solid var(--bkh-particles-line);
  & div { padding: 14px 10px 0 0; }
  & div + div { padding-inline-start: 14px; border-inline-start: 1px solid var(--bkh-particles-line); }
  & dt { font: 500 10.5px/1.3 var(--bkh-particles-mono); color: var(--bkh-particles-mute); letter-spacing: .02em; }
  & dd { margin: 6px 0 0; font-size: clamp(22px, 17px + 1.2cqi, 30px); font-weight: 700; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & small { font-size: .5em; font-weight: 600; margin-inline-start: 2px; color: var(--bkh-particles-mute); letter-spacing: 0; }
}

/* entrance */
.bkh-particles__main > *, .bkh-particles__side {
  transition: opacity .9s var(--bkh-particles-ease), translate .9s var(--bkh-particles-ease);
  @starting-style { opacity: 0; translate: 0 14px; }
}
.bkh-particles__main > :nth-child(2) { transition-delay: 80ms; }
.bkh-particles__main > :nth-child(3) { transition-delay: 160ms; }
.bkh-particles__main > :nth-child(4) { transition-delay: 240ms; }
.bkh-particles__side { transition-delay: 300ms; }

@container bkh-particles (min-width: 620px) {
  .bkh-particles__nav { display: flex; margin-inline-start: 18px; }
  .bkh-particles__tick--br { display: block; }
}
@container bkh-particles (min-width: 900px) {
  .bkh-particles__copy { grid-template-columns: minmax(0, 1.25fr) minmax(300px, .9fr); gap: 56px; align-items: end; }
}

@media (prefers-reduced-motion: reduce) {
  .bkh-particles__main > *, .bkh-particles__side { transition: none; @starting-style { opacity: 1; translate: none; } }
  .bkh-particles__btn, .bkh-particles__link svg { transition: none; }
}

js:
// Particle text. A word is rasterised once into an offscreen canvas, its opaque pixels
// are sampled on a grid, and each particle springs (under-damped) to one sample.
// Re-forming sweeps left to right via a per-particle delay keyed to target x.
// State lives in typed arrays; one pass updates, three batched passes draw.
const cv = root.querySelector(".bkh-particles__cv");
const field = root.querySelector(".bkh-particles__field");
const input = root.querySelector(".bkh-particles__input");
const form = root.querySelector(".bkh-particles__try");
const ptsEl = root.querySelector(".bkh-particles__pts");
const msEl = root.querySelector(".bkh-particles__ms");
const qEl = root.querySelector(".bkh-particles__q");
const sr = root.querySelector(".bkh-particles__sr");
const fallback = root.querySelector(".bkh-particles__fallback");
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
const uid = Math.random().toString(36).slice(2, 8);
input.id = "bkh-particles-q-" + uid;
root.querySelector(".bkh-particles__lbl").htmlFor = input.id;

const ctx = cv.getContext("2d");
if (!ctx) { root.classList.add("is-flat"); return; }
const off = document.createElement("canvas");
const octx = off.getContext("2d", { willReadFrequently: true });

const DEMO = ["meaning", "recall", "context", "answers"];
let demoIdx = 0, word = DEMO[0], userWord = "";
const N = 3600;
const X = new Float32Array(N), Y = new Float32Array(N), VX = new Float32Array(N), VY = new Float32Array(N);
const TX = new Float32Array(N), TY = new Float32Array(N), DL = new Float32Array(N), SEED = new Float32Array(N);
const HAS = new Uint8Array(N), VIS = new Uint8Array(N);
let dot = 2.4, dust = 200;
let W = 0, H = 0, dpr = 1, seeded = false;
let colHot = "#d7f25c", colInk = "#f2f2ea", colBg = "#20231b";

function readColours() {
  const cs = getComputedStyle(root);
  // Assigning an unsupported colour string is ignored, so the hex defaults survive.
  ctx.fillStyle = colHot; ctx.fillStyle = cs.getPropertyValue("--bkh-particles-hot").trim() || colHot; colHot = ctx.fillStyle;
  ctx.fillStyle = colInk; ctx.fillStyle = cs.getPropertyValue("--bkh-particles-ink").trim() || colInk; colInk = ctx.fillStyle;
  ctx.fillStyle = colBg; ctx.fillStyle = cs.getPropertyValue("--bkh-particles-bg").trim() || colBg; colBg = ctx.fillStyle;
}

function sample(text, sweep) {
  const t0 = performance.now();
  const rr = root.getBoundingClientRect(), fr = field.getBoundingClientRect();
  const fw = Math.max(20, Math.floor(fr.width)), fh = Math.max(20, Math.floor(fr.height));
  off.width = fw; off.height = fh;
  const fam = 'system-ui, -apple-system, "Segoe UI", Roboto, sans-serif';
  octx.font = "800 100px " + fam;
  const m = octx.measureText(text).width || 1;
  const fs = Math.min(fh * 0.86, (fw * 0.94) / (m / 100));
  octx.clearRect(0, 0, fw, fh);
  octx.font = "800 " + fs + "px " + fam;
  octx.textAlign = "center"; octx.textBaseline = "middle";
  octx.fillStyle = "#fff";
  octx.fillText(text, fw / 2, fh / 2 + fs * 0.03);
  const data = octx.getImageData(0, 0, fw, fh).data;
  const gap = Math.max(3, Math.min(6, Math.round(fs / 38)));
  dot = Math.max(1.8, gap * 0.62);
  dust = Math.round(Math.max(90, Math.min(240, (W * H) / 2800)));
  // pack (x,y) pairs on a staggered grid, then shuffle so each particle takes a random target
  const pairs = [];
  for (let y = 0; y < fh; y += gap)
    for (let x = (y / gap) % 2 ? gap >> 1 : 0; x < fw; x += gap)
      if (data[(y * fw + x) * 4 + 3] > 150) pairs.push(x + fr.left - rr.left, y + fr.top - rr.top);
  const count = Math.min(N, pairs.length >> 1);
  const order = new Uint32Array(pairs.length >> 1);
  for (let i = 0; i < order.length; i++) order[i] = i;
  for (let i = order.length - 1; i > 0; i--) { const j = (Math.random() * (i + 1)) | 0; const s = order[i]; order[i] = order[j]; order[j] = s; }
  const left = fr.left - rr.left;
  for (let i = 0; i < N; i++) {
    if (i < count) {
      const o = order[i];
      TX[i] = pairs[o * 2]; TY[i] = pairs[o * 2 + 1]; HAS[i] = 1;
      DL[i] = sweep ? ((TX[i] - left) / fw) * 26 + Math.random() * 12 : 0;
      VIS[i] = 1;
    } else {
      // a few hundred stay as drifting dust; the rest park, unseen and unsimulated
      HAS[i] = 0; DL[i] = 0; VIS[i] = i < count + dust ? 1 : 0;
    }
  }
  ptsEl.textContent = count.toLocaleString("en-US");
  msEl.textContent = (performance.now() - t0).toFixed(1);
  qEl.textContent = text;
  fallback.textContent = text;
  return count;
}

function seed() {
  for (let i = 0; i < N; i++) {
    X[i] = Math.random() * W; Y[i] = Math.random() * H;
    VX[i] = 0; VY[i] = 0; SEED[i] = Math.random() * 6.283;
  }
  seeded = true;
}
function snap() { for (let i = 0; i < N; i++) if (HAS[i]) { X[i] = TX[i]; Y[i] = TY[i]; VX[i] = VY[i] = 0; } }

let mx = -1e5, my = -1e5, t = 0;
function step() {
  t += 0.016;
  const R = Math.max(70, Math.min(130, W * 0.1)), R2 = R * R;
  for (let i = 0; i < N; i++) {
    if (!VIS[i]) continue;
    let vx = VX[i], vy = VY[i];
    if (HAS[i] && DL[i] <= 0) {
      vx += (TX[i] - X[i]) * 0.022;
      vy += (TY[i] - Y[i]) * 0.022;
      vx *= 0.86; vy *= 0.86;
    } else {
      if (DL[i] > 0) DL[i] -= 1;
      const s = SEED[i];
      vx += Math.cos(t * 0.6 + s) * 0.03; vy += Math.sin(t * 0.5 + s * 1.7) * 0.03 - 0.004;
      vx *= 0.96; vy *= 0.96;
    }
    const dx = X[i] - mx, dy = Y[i] - my, d2 = dx * dx + dy * dy;
    if (d2 < R2 && d2 > 0.01) {
      const d = Math.sqrt(d2), f = (1 - d / R) * 2.6;
      vx += (dx / d) * f; vy += (dy / d) * f;
    }
    X[i] += vx; Y[i] += vy; VX[i] = vx; VY[i] = vy;
    if (!HAS[i]) {
      if (X[i] < -4) X[i] += W + 8; else if (X[i] > W + 4) X[i] -= W + 8;
      if (Y[i] < -4) Y[i] += H + 8; else if (Y[i] > H + 4) Y[i] -= H + 8;
    }
  }
}
function draw(trail) {
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.globalAlpha = trail ? 0.46 : 1;
  ctx.fillStyle = colBg;
  ctx.fillRect(0, 0, W, H);
  // dust
  ctx.globalAlpha = 0.24; ctx.fillStyle = colHot;
  for (let i = 0; i < N; i++) if (VIS[i] && (!HAS[i] || DL[i] > 0)) ctx.fillRect(X[i] - 0.7, Y[i] - 0.7, 1.4, 1.4);
  // in flight: pale, larger
  const h = dot / 2;
  ctx.globalAlpha = 0.9; ctx.fillStyle = colInk;
  for (let i = 0; i < N; i++) if (HAS[i] && DL[i] <= 0 && VX[i] * VX[i] + VY[i] * VY[i] > 1.2) ctx.fillRect(X[i] - h, Y[i] - h, dot, dot);
  // settled: the word
  ctx.globalAlpha = 1; ctx.fillStyle = colHot;
  for (let i = 0; i < N; i++) if (HAS[i] && DL[i] <= 0 && VX[i] * VX[i] + VY[i] * VY[i] <= 1.2) ctx.fillRect(X[i] - h, Y[i] - h, dot, dot);
}

let raf = 0, running = false, visible = false, disposed = false;
function frame() {
  if (!root.isConnected) return dispose();
  if (!visible || document.hidden) { running = false; return; }
  step(); draw(true);
  raf = requestAnimationFrame(frame);
}
function start() {
  if (running || disposed || reduce || !W) return;
  running = true; raf = requestAnimationFrame(frame);
}
function setWord(w, sweep) {
  word = w;
  sample(w, sweep && !reduce);
  if (reduce || !running) { if (reduce) snap(); draw(false); }
}

const ro = new ResizeObserver(() => {
  dpr = Math.min(2, window.devicePixelRatio || 1);
  W = cv.clientWidth; H = cv.clientHeight;
  if (!W || !H) return;
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  readColours();
  if (!seeded) seed();
  sample(word, false);
  if (reduce) snap();
  draw(false);
  if (visible) start();
});
ro.observe(cv);

// demo cycle, suspended while the visitor has their own word in the box
const cycle = setInterval(() => {
  if (!root.isConnected) return dispose();
  if (reduce || userWord || !visible || document.hidden || document.activeElement === input) return;
  demoIdx = (demoIdx + 1) % DEMO.length;
  setWord(DEMO[demoIdx], true);
}, 4200);

let debounce = 0;
input.addEventListener("input", () => {
  clearTimeout(debounce);
  debounce = setTimeout(() => {
    if (!root.isConnected) return;
    const v = input.value.trim().slice(0, 12);
    userWord = v;
    if (v && v !== word) setWord(v, true);
  }, 260);
});
form.addEventListener("submit", (e) => {
  e.preventDefault();
  const v = input.value.trim().slice(0, 12);
  if (!v) return;
  userWord = v;
  setWord(v, true);
  sr.textContent = "Headline re-indexed as " + v + ", " + ptsEl.textContent + " particles.";
});
input.addEventListener("keydown", (e) => {
  if (e.key !== "Escape") return;
  input.value = ""; userWord = "";
  setWord(DEMO[demoIdx], true);
  sr.textContent = "Demo restored.";
});

root.addEventListener("pointermove", (e) => {
  const r = root.getBoundingClientRect();
  mx = e.clientX - r.left; my = e.clientY - r.top;
});
root.addEventListener("pointerleave", () => { mx = my = -1e5; });

const io = new IntersectionObserver((es) => {
  visible = es[es.length - 1].isIntersecting;
  if (visible) start();
}, { rootMargin: "80px" });
io.observe(root);

function dispose() {
  if (disposed) return;
  disposed = true; running = false;
  cancelAnimationFrame(raf); clearInterval(cycle); clearTimeout(debounce);
  io.disconnect(); ro.disconnect();
}

css:
/* Pipewren — a light developer-tool hero with a scripted terminal.
   Re-theme: --bkh-terminal-paper, -ink, -go (success/brand), -warn, -err. */
.bkh-terminal {
  --bkh-terminal-paper: oklch(0.972 0.006 95);
  --bkh-terminal-ink: oklch(0.22 0.015 260);
  --bkh-terminal-go: oklch(0.56 0.14 152);
  --bkh-terminal-warn: oklch(0.66 0.15 62);
  --bkh-terminal-err: oklch(0.58 0.19 27);
  --bkh-terminal-card: color-mix(in oklch, var(--bkh-terminal-paper), white 80%);
  --bkh-terminal-line: color-mix(in oklch, var(--bkh-terminal-ink) 11%, transparent);
  --bkh-terminal-mute: color-mix(in oklch, var(--bkh-terminal-ink) 58%, var(--bkh-terminal-paper));
  --bkh-terminal-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bkh-terminal-ease: cubic-bezier(.2, .8, .2, 1);

  container-type: inline-size;
  container-name: bkh-terminal;
  position: relative; isolation: isolate; overflow: hidden;
  width: 100%;
  border-radius: 16px;
  background: var(--bkh-terminal-paper);
  color: var(--bkh-terminal-ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  &::before {
    content: ""; position: absolute; inset: 0; z-index: -1;
    background: radial-gradient(circle, color-mix(in oklch, var(--bkh-terminal-ink) 16%, transparent) 1px, transparent 1.5px) 0 0 / 22px 22px;
    mask-image: radial-gradient(70% 70% at 75% 45%, black, transparent 75%);
  }
  & :where(a) { color: inherit; text-decoration: none; }
  & :focus-visible { outline: 2px solid var(--bkh-terminal-go); outline-offset: 2px; border-radius: 6px; }
}
.bkh-terminal__in {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "bar" "copy" "term";
  gap: 30px;
  padding: clamp(16px, 4.2cqi, 50px);
}
.bkh-terminal__bar { grid-area: bar; display: flex; align-items: center; gap: 22px; font-size: 14px; }
.bkh-terminal__logo {
  display: inline-flex; align-items: center; gap: 8px; font: 700 16px/1 var(--bkh-terminal-mono); letter-spacing: -.03em;
  & svg { width: 24px; height: 24px; fill: none; stroke: var(--bkh-terminal-go); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  & circle { fill: var(--bkh-terminal-go); stroke: none; }
}
.bkh-terminal__nav { display: none; gap: 22px; color: var(--bkh-terminal-mute); & a:hover { color: var(--bkh-terminal-ink); } }
.bkh-terminal__signin { margin-inline-start: auto; font-weight: 600; }

.bkh-terminal__copy { grid-area: copy; align-self: center; }
.bkh-terminal__news {
  display: inline-flex; align-items: center; gap: 9px; margin-bottom: 20px;
  padding: 4px 10px 4px 4px; border-radius: 999px; border: 1px solid var(--bkh-terminal-line); background: var(--bkh-terminal-card);
  font-size: 13px; font-weight: 500;
  & span { font: 600 11px/1 var(--bkh-terminal-mono); padding: 5px 7px; border-radius: 999px; background: color-mix(in oklch, var(--bkh-terminal-go) 14%, white); color: color-mix(in oklch, var(--bkh-terminal-go), black 25%); }
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; transition: translate .3s var(--bkh-terminal-ease); }
  &:hover svg { translate: 3px 0; }
}
.bkh-terminal__title {
  margin: 0; max-width: 15ch;
  font-size: clamp(2.1rem, 1rem + 4.4cqi, 4rem); line-height: 1.02; letter-spacing: -.04em; font-weight: 700;
  text-wrap: balance;
}
.bkh-terminal__lede { margin: 18px 0 0; max-width: 46ch; font-size: clamp(15px, 13.5px + .35cqi, 17px); line-height: 1.6; color: var(--bkh-terminal-mute); text-wrap: pretty; }
.bkh-terminal__cta { margin-top: 26px; display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.bkh-terminal__btn {
  padding: 12px 18px; border-radius: 10px; background: var(--bkh-terminal-ink); color: var(--bkh-terminal-paper); font-weight: 600; font-size: 14.5px;
  box-shadow: 0 1px 0 color-mix(in oklch, white 25%, transparent) inset, 0 6px 16px -8px var(--bkh-terminal-ink);
  transition: translate .25s var(--bkh-terminal-ease), background .25s;
  &:hover { translate: 0 -1px; background: color-mix(in oklch, var(--bkh-terminal-ink), var(--bkh-terminal-go) 25%); }
}
.bkh-terminal__copycmd {
  display: inline-flex; align-items: center; gap: 12px; cursor: pointer;
  padding: 11px 12px 11px 14px; border-radius: 10px;
  border: 1px solid var(--bkh-terminal-line); background: var(--bkh-terminal-card); color: inherit; font: inherit;
  transition: border-color .25s, background .25s;
  & code { font: 500 14px/1 var(--bkh-terminal-mono); }
  & code span { color: var(--bkh-terminal-mute); }
  & svg { width: 17px; height: 17px; fill: none; stroke: var(--bkh-terminal-mute); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  & .bkh-terminal__i-ok { display: none; stroke: var(--bkh-terminal-go); stroke-width: 2.2; }
  &.is-copied .bkh-terminal__i-ok { display: block; animation: bkh-terminal-pop .45s cubic-bezier(.34, 1.56, .64, 1); }
  &.is-copied .bkh-terminal__i-copy { display: none; }
  &:hover { border-color: color-mix(in oklch, var(--bkh-terminal-ink) 30%, transparent); }
}
@keyframes bkh-terminal-pop { from { scale: .4; opacity: 0; } }
.bkh-terminal__copied { font: 500 12px/1 var(--bkh-terminal-mono); color: var(--bkh-terminal-go); }
.bkh-terminal__proof {
  margin-top: 34px;
  & p { margin: 0 0 12px; font-size: 12.5px; color: var(--bkh-terminal-mute); }
  & ul { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 10px 22px; }
  & li { display: inline-flex; align-items: center; gap: 7px; font-weight: 650; font-size: 14px; letter-spacing: -.02em; color: color-mix(in oklch, var(--bkh-terminal-ink) 70%, var(--bkh-terminal-paper)); }
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
}

/* ---- terminal ---- */
.bkh-terminal__term {
  grid-area: term; align-self: center; min-width: 0;
  border-radius: 14px; overflow: hidden;
  background: var(--bkh-terminal-card);
  border: 1px solid color-mix(in oklch, var(--bkh-terminal-ink) 14%, transparent);
  box-shadow: 0 1px 0 white inset, 0 2px 4px color-mix(in oklch, var(--bkh-terminal-ink) 6%, transparent), 0 30px 60px -30px color-mix(in oklch, var(--bkh-terminal-ink) 35%, transparent);
  font-family: var(--bkh-terminal-mono);
}
.bkh-terminal__chrome {
  display: flex; align-items: center; gap: 12px; padding: 8px 8px 8px 14px;
  border-bottom: 1px solid var(--bkh-terminal-line);
  background: color-mix(in oklch, var(--bkh-terminal-paper), var(--bkh-terminal-ink) 2%);
}
.bkh-terminal__dots { display: inline-flex; gap: 6px; & i { width: 10px; height: 10px; border-radius: 50%; border: 1.5px solid color-mix(in oklch, var(--bkh-terminal-ink) 22%, transparent); } }
.bkh-terminal__tabs {
  display: flex; gap: 2px; margin-inline: auto; padding: 3px; border-radius: 9px; background: color-mix(in oklch, var(--bkh-terminal-ink) 5%, transparent);
  & button {
    appearance: none; border: 0; background: none; color: var(--bkh-terminal-mute); cursor: pointer;
    font: 500 12px/1 var(--bkh-terminal-mono); padding: 6px 12px; border-radius: 7px;
    transition: color .2s, background .25s var(--bkh-terminal-ease), box-shadow .25s;
  }
  & button:hover { color: var(--bkh-terminal-ink); }
  & button[aria-selected="true"] { color: var(--bkh-terminal-ink); background: var(--bkh-terminal-card); box-shadow: 0 1px 2px color-mix(in oklch, var(--bkh-terminal-ink) 15%, transparent); }
}
.bkh-terminal__replay {
  appearance: none; border: 0; background: none; color: var(--bkh-terminal-mute); cursor: pointer;
  width: 30px; height: 30px; display: grid; place-items: center; border-radius: 7px;
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; transition: rotate .5s var(--bkh-terminal-ease); }
  &:hover { background: color-mix(in oklch, var(--bkh-terminal-ink) 6%, transparent); color: var(--bkh-terminal-ink); }
  &:hover svg { rotate: -50deg; }
}
.bkh-terminal__screen {
  position: relative;
  height: clamp(270px, 36cqi, 360px);
  overflow-y: auto; overscroll-behavior: contain;
  padding: 0 16px 14px;
  font-size: clamp(11.5px, 10px + .35cqi, 13px); line-height: 1.75;
  scrollbar-width: thin; scrollbar-color: var(--bkh-terminal-line) transparent;
  outline: none;
  &:focus-visible { box-shadow: inset 0 0 0 2px var(--bkh-terminal-go); }
}
.bkh-terminal__fade {
  position: sticky; top: 0; z-index: 1; height: 26px; margin: 0 -16px -26px;
  background: linear-gradient(var(--bkh-terminal-card), transparent);
  opacity: 0; pointer-events: none;
}
@supports (animation-timeline: scroll()) {
  .bkh-terminal__fade { animation: bkh-terminal-fade linear both; animation-timeline: scroll(nearest block); animation-range: 0 48px; }
}
@keyframes bkh-terminal-fade { to { opacity: 1; } }
.bkh-terminal__out { padding-top: 14px; }
.bkh-terminal__ln {
  white-space: pre-wrap; word-break: break-word; min-height: 1.75em;
  animation: bkh-terminal-ln .35s var(--bkh-terminal-ease) both;
}
@keyframes bkh-terminal-ln { from { opacity: 0; translate: 0 4px; } }
.bkh-terminal__ln--cmd { animation: none; }
.bkh-terminal__ps { color: var(--bkh-terminal-go); font-weight: 700; }
.bkh-terminal__caret {
  display: inline-block; width: .6em; height: 1.15em; vertical-align: -.2em; margin-inline-start: 1px;
  background: var(--bkh-terminal-ink); animation: bkh-terminal-caret 1s steps(2, jump-none) infinite;
}
@keyframes bkh-terminal-caret { 50% { opacity: 0; } }
.bkh-terminal__m { color: var(--bkh-terminal-mute); }
.bkh-terminal__ok { color: var(--bkh-terminal-go); font-weight: 600; }
.bkh-terminal__w { color: var(--bkh-terminal-warn); font-weight: 600; }
.bkh-terminal__e { color: var(--bkh-terminal-err); font-weight: 600; }
.bkh-terminal__b { font-weight: 700; }
.bkh-terminal__link { color: var(--bkh-terminal-go); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; }
.bkh-terminal__spin { display: inline-block; width: 1ch; margin-inline-end: 1ch; color: var(--bkh-terminal-warn); }
.bkh-terminal__track {
  display: inline-block; width: 10ch; height: .5em; margin-inline: 1ch; vertical-align: .1em;
  border-radius: 99px; background: var(--bkh-terminal-line); overflow: hidden;
  & i { display: block; height: 100%; background: var(--bkh-terminal-warn); transform-origin: left; scale: 0 1; transition: scale var(--d, 1s) linear; }
}
.bkh-terminal__opt { color: var(--bkh-terminal-mute); }

.bkh-terminal__status {
  display: flex; justify-content: space-between; align-items: center; gap: 12px;
  padding: 8px 14px; border-top: 1px solid var(--bkh-terminal-line);
  font-size: 11.5px; color: var(--bkh-terminal-mute);
}
.bkh-terminal__state {
  display: inline-flex; align-items: center; gap: 7px; color: var(--bkh-terminal-ink); font-weight: 600;
  & i { width: 8px; height: 8px; border-radius: 50%; background: var(--bkh-terminal-mute); transition: background .3s; }
}
.bkh-terminal[data-state="run"] .bkh-terminal__state i { background: var(--bkh-terminal-warn); animation: bkh-terminal-pulse 1s ease-in-out infinite; }
.bkh-terminal[data-state="live"] .bkh-terminal__state i { background: var(--bkh-terminal-go); box-shadow: 0 0 0 3px color-mix(in oklch, var(--bkh-terminal-go) 22%, transparent); }
@keyframes bkh-terminal-pulse { 50% { opacity: .35; } }
.bkh-terminal__meta { display: none; }

@container bkh-terminal (min-width: 560px) {
  .bkh-terminal__nav { display: flex; margin-inline-start: 16px; }
  .bkh-terminal__meta { display: inline; }
}
@container bkh-terminal (max-width: 479px) {
  .bkh-terminal__opt { display: none; }
  .bkh-terminal__track { width: 6ch; }
}
@container bkh-terminal (min-width: 920px) {
  .bkh-terminal__in {
    grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr);
    grid-template-areas: "bar bar" "copy term";
    column-gap: 52px; row-gap: 44px;
  }
  .bkh-terminal__term { transform: perspective(1600px) rotateY(-5deg); transition: transform .9s var(--bkh-terminal-ease); }
  .bkh-terminal__term:hover, .bkh-terminal__term:focus-within { transform: perspective(1600px) rotateY(0deg); }
}

@media (prefers-reduced-motion: reduce) {
  .bkh-terminal__ln, .bkh-terminal__caret, .bkh-terminal[data-state="run"] .bkh-terminal__state i { animation: none; }
  .bkh-terminal__track i { transition: none; }
  .bkh-terminal__term, .bkh-terminal__news svg, .bkh-terminal__replay svg, .bkh-terminal__btn { transition: none; }
  .bkh-terminal__copycmd.is-copied .bkh-terminal__i-ok { animation: none; }
}

js:
// Scripted terminal. Each script is data: a typed command, then lines and "tasks"
// (spinner + progress bar that resolves into a result). A generation counter cancels
// a running script when the visitor switches tab; every await re-checks that the
// root is still mounted and on screen, so nothing runs while it cannot be seen.
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
const out = root.querySelector(".bkh-terminal__out");
const screen = root.querySelector(".bkh-terminal__screen");
const stateText = root.querySelector(".bkh-terminal__statetext");
const tabs = Array.from(root.querySelectorAll(".bkh-terminal__tabs [role=tab]"));
const uid = Math.random().toString(36).slice(2, 8);
screen.id = "bkh-terminal-out-" + uid;
tabs.forEach((t, i) => { t.id = "bkh-terminal-tab-" + uid + "-" + i; t.setAttribute("aria-controls", screen.id); });

// [class, text] segments. "o" marks optional columns hidden in narrow containers.
const SCRIPTS = {
  up: [
    { cmd: "wren up --branch feat/checkout-v2" },
    { line: [["m", "▸ Resolving "], ["b", "feat/checkout-v2"], ["m", " @ a41c9e2"], ["o", "  (3 commits ahead of main)"]] },
    { task: "Building web", ms: 1300, done: [["ok", "✓ "], ["", "web       "], ["b", "38.2s"], ["o", "   cache hit 74%"]] },
    { task: "Building api", ms: 900, done: [["ok", "✓ "], ["", "api       "], ["b", "21.6s"], ["o", "   cache hit 91%"]] },
    { task: "Seeding database", ms: 650, done: [["ok", "✓ "], ["", "database   "], ["b", "4.1s"], ["o", "   snapshot prod-0930, anonymised"]] },
    { task: "Health checks", ms: 750, done: [["ok", "✓ "], ["", "health     "], ["b", "6.1s"], ["o", "   6/6 passing"]] },
    { line: [] },
    { line: [["ok", "→ Preview live  "], ["link", "checkout-v2.pipewren.app"]], state: ["live", "Preview live"] },
    { line: [["m", "↳ Commented on PR #1842"], ["o", " · 3 reviewers notified"]] },
    { line: [["m", "Done in "], ["b", "70.0s"]] }
  ],
  logs: [
    { cmd: "wren logs api --follow" },
    { line: [["m", "14:02:11.204  "], ["", "GET  /api/cart            "], ["ok", "200"], ["m", "   12 ms"]], gap: 260 },
    { line: [["m", "14:02:11.388  "], ["", "POST /api/cart/items      "], ["ok", "201"], ["m", "   38 ms"]], gap: 380 },
    { line: [["m", "14:02:12.019  "], ["", "GET  /api/shipping/rates  "], ["ok", "200"], ["m", "   96 ms"]], gap: 520 },
    { line: [["m", "14:02:12.733  "], ["", "POST /api/checkout        "], ["e", "402"], ["m", "  141 ms"], ["o", "  declined"]], gap: 640 },
    { line: [["m", "14:02:13.105  "], ["", "POST /api/checkout        "], ["ok", "200"], ["m", "  188 ms"]], gap: 420 },
    { line: [["m", "14:02:13.420  "], ["", "GET  /api/orders/7731     "], ["ok", "200"], ["m", "    9 ms"]], gap: 300 },
    { line: [["m", "── 6 requests · "], ["e", "1 error"], ["m", " · p50 67 ms"]], gap: 500, state: ["live", "Streaming logs"] }
  ],
  down: [
    { cmd: "wren down feat/checkout-v2" },
    { task: "Snapshotting database", ms: 800, done: [["ok", "✓ "], ["", "snapshot saved   "], ["b", "1.8s"], ["o", "   db-checkout-v2-1842"]] },
    { task: "Destroying preview", ms: 1100, done: [["ok", "✓ "], ["", "preview removed  "], ["b", "3.4s"], ["o", "   3 services, 1 volume"]] },
    { line: [["ok", "✓ "], ["", "Freed 2 vCPU · 4 GB memory"]] },
    { line: [] },
    { line: [["m", "This week: "], ["b", "31 previews"], ["m", " · "], ["w", "412 compute-hours"], ["m", " saved by auto-sleep"]], state: ["idle", "Preview destroyed"] }
  ]
};

let gen = 0, visible = false, disposed = false, current = "up";
const timers = new Set(), wakers = new Set();
function sleep(ms) {
  return new Promise((res) => {
    const id = setTimeout(() => { timers.delete(id); res(); }, reduce ? 0 : ms);
    timers.add(id);
  });
}
function onScreen() {
  if (visible && !document.hidden) return Promise.resolve();
  return new Promise((res) => wakers.add(res));
}
function alive(my) { return my === gen && root.isConnected && !disposed; }

function seg(parts) {
  const ln = document.createElement("div");
  ln.className = "bkh-terminal__ln";
  parts.forEach(([cls, text]) => {
    const s = document.createElement("span");
    if (cls === "o") s.className = "bkh-terminal__opt";
    else if (cls) s.className = "bkh-terminal__" + cls;
    s.textContent = text;
    ln.append(s);
  });
  if (!parts.length) ln.textContent = " ";
  return ln;
}
function scroll() { screen.scrollTop = screen.scrollHeight; }
function setState(s, text) { root.dataset.state = s; stateText.textContent = text; }

async function run(name) {
  const my = ++gen;
  current = name;
  out.replaceChildren();
  screen.scrollTop = 0;
  setState("idle", "Ready");
  for (const step of SCRIPTS[name]) {
    await onScreen();
    if (!alive(my)) return;
    if (step.cmd) {
      const ln = document.createElement("div");
      ln.className = "bkh-terminal__ln bkh-terminal__ln--cmd";
      const ps = document.createElement("span"); ps.className = "bkh-terminal__ps"; ps.textContent = "$ ";
      const txt = document.createElement("span");
      const caret = document.createElement("span"); caret.className = "bkh-terminal__caret";
      ln.append(ps, txt, caret); out.append(ln);
      await sleep(350);
      for (const ch of step.cmd) {
        if (!alive(my)) return;
        txt.textContent += ch;
        await sleep(24 + Math.random() * 46 + (ch === " " ? 60 : 0));
      }
      await sleep(320);
      if (!alive(my)) return;
      caret.remove();
      setState("run", "Running");
    } else if (step.task) {
      const ln = document.createElement("div");
      ln.className = "bkh-terminal__ln";
      const spin = document.createElement("span"); spin.className = "bkh-terminal__spin";
      const label = document.createElement("span"); label.textContent = step.task;
      const track = document.createElement("span"); track.className = "bkh-terminal__track";
      const fill = document.createElement("i"); track.append(fill);
      track.style.setProperty("--d", step.ms + "ms");
      ln.append(spin, label, track); out.append(ln); scroll();
      const frames = "⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏";
      let f = 0;
      spin.textContent = frames[0];
      const iv = setInterval(() => {
        if (!root.isConnected) { clearInterval(iv); return; }
        spin.textContent = frames[(f = (f + 1) % frames.length)];
      }, 80);
      requestAnimationFrame(() => { if (!root.isConnected) return; fill.style.scale = "1 1"; });
      await sleep(step.ms);
      clearInterval(iv);
      if (!alive(my)) return;
      ln.replaceWith(seg(step.done));
      scroll();
    } else {
      await sleep(step.gap || 180);
      if (!alive(my)) return;
      out.append(seg(step.line)); scroll();
      if (step.state) setState(step.state[0], step.state[1]);
    }
  }
}

function select(i, focus) {
  tabs.forEach((t, j) => { t.setAttribute("aria-selected", String(j === i)); t.tabIndex = j === i ? 0 : -1; });
  screen.setAttribute("aria-labelledby", tabs[i].id);
  if (focus) tabs[i].focus();
  run(tabs[i].dataset.run);
}
tabs.forEach((t, i) => t.addEventListener("click", () => select(i, false)));
root.querySelector(".bkh-terminal__tabs").addEventListener("keydown", (e) => {
  const i = tabs.findIndex((t) => t.getAttribute("aria-selected") === "true");
  let n = i;
  if (e.key === "ArrowRight") n = (i + 1) % tabs.length;
  else if (e.key === "ArrowLeft") n = (i - 1 + tabs.length) % tabs.length;
  else if (e.key === "Home") n = 0;
  else if (e.key === "End") n = tabs.length - 1;
  else return;
  e.preventDefault();
  select(n, true);
});
root.querySelector(".bkh-terminal__replay").addEventListener("click", () => run(current));

// copy-to-clipboard, with a selection fallback where the async API is unavailable
const copyBtn = root.querySelector(".bkh-terminal__copycmd");
const copied = root.querySelector(".bkh-terminal__copied");
let copyTimer = 0;
copyBtn.addEventListener("click", () => {
  const done = () => {
    copyBtn.classList.add("is-copied"); copied.textContent = "Copied";
    clearTimeout(copyTimer);
    copyTimer = setTimeout(() => {
      if (!root.isConnected) return;
      copyBtn.classList.remove("is-copied"); copied.textContent = "";
    }, 1800);
  };
  const text = "wren up";
  if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text).then(done, done);
  else {
    const r = document.createRange(); r.selectNodeContents(copyBtn.querySelector("code"));
    const sel = getSelection(); sel.removeAllRanges(); sel.addRange(r); done();
  }
});

const io = new IntersectionObserver((es) => {
  visible = es[es.length - 1].isIntersecting;
  if (visible) { wakers.forEach((w) => w()); wakers.clear(); }
}, { threshold: 0.25 });
io.observe(root);
const beat = setInterval(() => {
  if (!root.isConnected) return dispose();
  if (visible && !document.hidden && wakers.size) { wakers.forEach((w) => w()); wakers.clear(); }
}, 1000);
function dispose() {
  if (disposed) return;
  disposed = true; gen++;
  timers.forEach(clearTimeout); timers.clear(); wakers.clear();
  clearTimeout(copyTimer); clearInterval(beat); io.disconnect();
}

screen.setAttribute("aria-labelledby", tabs[0].id);
run("up");

css:
/* Antipode — dotted globe with great-circle arcs on a 2D canvas.
   Re-theme: --bkh-globe-bg, -ink, -land, -arc. The canvas reads the same variables. */
.bkh-globe {
  --bkh-globe-bg: oklch(0.17 0.018 170);
  --bkh-globe-ink: oklch(0.95 0.012 120);
  --bkh-globe-land: oklch(0.80 0.045 155);
  --bkh-globe-arc: oklch(0.83 0.15 74);
  --bkh-globe-mute: color-mix(in oklch, var(--bkh-globe-ink) 60%, var(--bkh-globe-bg));
  --bkh-globe-line: color-mix(in oklch, var(--bkh-globe-ink) 12%, transparent);
  --bkh-globe-panel: color-mix(in oklch, var(--bkh-globe-bg), var(--bkh-globe-ink) 5%);
  --bkh-globe-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bkh-globe-ease: cubic-bezier(.16, 1, .3, 1);

  container-type: inline-size;
  container-name: bkh-globe;
  position: relative; isolation: isolate; overflow: hidden;
  width: 100%;
  border-radius: 20px;
  background:
    radial-gradient(55% 60% at 74% 52%, color-mix(in oklch, var(--bkh-globe-land) 9%, transparent), transparent 70%),
    var(--bkh-globe-bg);
  color: var(--bkh-globe-ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  & :where(a) { color: inherit; text-decoration: none; }
  & :focus-visible { outline: 2px solid var(--bkh-globe-arc); outline-offset: 3px; border-radius: 8px; }
}
.bkh-globe__in {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "bar" "copy" "viz";
  gap: 26px;
  padding: clamp(16px, 4.2cqi, 50px);
}
.bkh-globe__bar { grid-area: bar; display: flex; align-items: center; gap: 24px; font-size: 14px; }
.bkh-globe__logo {
  display: inline-flex; align-items: center; gap: 9px; font-weight: 700; font-size: 17px; letter-spacing: -.02em;
  & svg { width: 26px; height: 26px; fill: none; stroke: var(--bkh-globe-arc); stroke-width: 1.6; stroke-linecap: round; }
  & circle + circle { fill: var(--bkh-globe-arc); stroke: none; }
}
.bkh-globe__nav { display: none; gap: 24px; color: var(--bkh-globe-mute); & a:hover { color: var(--bkh-globe-ink); } }
.bkh-globe__start {
  margin-inline-start: auto; padding: 8px 14px; border-radius: 999px; font-weight: 600; font-size: 13.5px;
  background: var(--bkh-globe-ink); color: var(--bkh-globe-bg);
  transition: background .25s;
  &:hover { background: var(--bkh-globe-arc); }
}

.bkh-globe__copy { grid-area: copy; align-self: center; position: relative; z-index: 1; }
.bkh-globe__eyebrow {
  margin: 0 0 18px; display: flex; flex-wrap: wrap; gap: 6px;
  & span { font: 500 11.5px/1 var(--bkh-globe-mono); padding: 6px 9px; border-radius: 999px; border: 1px solid var(--bkh-globe-line); color: var(--bkh-globe-mute); }
  & span:first-child { color: var(--bkh-globe-arc); border-color: color-mix(in oklch, var(--bkh-globe-arc) 40%, transparent); }
}
.bkh-globe__title {
  margin: 0; max-width: 14ch;
  font-size: clamp(2.2rem, 1rem + 4.6cqi, 4.3rem); font-weight: 650; line-height: 1.02; letter-spacing: -.04em;
  text-wrap: balance;
}
.bkh-globe__lede { margin: 18px 0 0; max-width: 46ch; font-size: clamp(15px, 13.5px + .35cqi, 17px); line-height: 1.6; color: var(--bkh-globe-mute); text-wrap: pretty; }
.bkh-globe__pick {
  margin: 26px 0 0; padding: 0; border: 0; min-width: 0;
  display: flex; flex-wrap: wrap; gap: 6px;
  & legend { padding: 0 0 10px; font: 600 11px/1 var(--bkh-globe-mono); letter-spacing: .1em; text-transform: uppercase; color: var(--bkh-globe-mute); }
}
.bkh-globe__chip {
  position: relative; display: inline-flex; align-items: baseline; gap: 7px; cursor: pointer;
  padding: 8px 12px; border-radius: 10px; border: 1px solid var(--bkh-globe-line);
  font-size: 13.5px; font-weight: 500;
  transition: border-color .25s, background .25s, color .25s;
  & input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; accent-color: var(--bkh-globe-arc); }
  & small { font: 500 10.5px/1 var(--bkh-globe-mono); color: var(--bkh-globe-mute); }
  &:hover { border-color: color-mix(in oklch, var(--bkh-globe-ink) 30%, transparent); }
  &:has(input:checked) { background: color-mix(in oklch, var(--bkh-globe-arc) 16%, transparent); border-color: var(--bkh-globe-arc); }
  &:has(input:checked) small { color: var(--bkh-globe-arc); }
  &:has(input:focus-visible) { outline: 2px solid var(--bkh-globe-arc); outline-offset: 2px; }
}
.bkh-globe__cta { margin-top: 28px; display: flex; flex-wrap: wrap; align-items: center; gap: 12px 22px; }
.bkh-globe__btn {
  display: inline-flex; align-items: center; gap: 10px; padding: 13px 18px; border-radius: 12px;
  background: var(--bkh-globe-arc); color: var(--bkh-globe-bg); font-weight: 650; font-size: 14.5px;
  transition: translate .3s var(--bkh-globe-ease), box-shadow .3s var(--bkh-globe-ease);
  & svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; transition: translate .3s var(--bkh-globe-ease); }
  &:hover { translate: 0 -2px; box-shadow: 0 12px 30px -10px color-mix(in oklch, var(--bkh-globe-arc) 70%, transparent); }
  &:hover svg { translate: 3px 0; }
}
.bkh-globe__link { font-weight: 600; font-size: 14.5px; color: var(--bkh-globe-mute); transition: color .2s; &:hover { color: var(--bkh-globe-ink); } }

/* ---- globe + readout ---- */
.bkh-globe__viz { grid-area: viz; position: relative; min-width: 0; display: grid; gap: 14px; }
.bkh-globe__cv {
  display: block; width: 100%; aspect-ratio: 1 / .92;
  cursor: grab; touch-action: pan-y;
  &:active { cursor: grabbing; }
}
.bkh-globe__hint {
  position: absolute; top: 4px; right: 0; margin: 0;
  font: 500 10.5px/1 var(--bkh-globe-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--bkh-globe-mute);
  transition: opacity .6s;
}
.bkh-globe.is-dragged .bkh-globe__hint { opacity: 0; }
.bkh-globe__readout {
  padding: 14px 16px; border-radius: 14px;
  background: color-mix(in oklch, var(--bkh-globe-panel) 88%, transparent);
  border: 1px solid var(--bkh-globe-line);
  backdrop-filter: blur(10px);
  font-size: 13px;
}
.bkh-globe__rhd { margin: 0 0 10px; color: var(--bkh-globe-mute); & b { color: var(--bkh-globe-ink); font-weight: 600; } }
.bkh-globe__rows { list-style: none; margin: 0; padding: 0; display: grid; gap: 7px; }
.bkh-globe__row {
  display: grid; grid-template-columns: 7.5em 1fr auto; align-items: center; gap: 10px;
  font-variant-numeric: tabular-nums;
  transition: opacity .6s var(--bkh-globe-ease), translate .6s var(--bkh-globe-ease);
  transition-delay: calc(var(--i) * 60ms);
  @starting-style { opacity: 0; translate: -8px 0; }
  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { color: var(--bkh-globe-mute); font: 500 11px/1 var(--bkh-globe-mono); margin-inline-start: 4px; }
  & b { font: 600 12.5px/1 var(--bkh-globe-mono); min-width: 5ch; text-align: end; }
}
.bkh-globe__meter {
  height: 4px; border-radius: 99px; background: var(--bkh-globe-line); overflow: hidden;
  & i { display: block; height: 100%; width: var(--w); border-radius: inherit; background: linear-gradient(90deg, color-mix(in oklch, var(--bkh-globe-arc) 50%, transparent), var(--bkh-globe-arc));
    transition: width .9s var(--bkh-globe-ease); transition-delay: calc(var(--i) * 60ms + 100ms);
    @starting-style { width: 0; } }
}
.bkh-globe__rft {
  margin: 12px 0 0; padding-top: 10px; border-top: 1px solid var(--bkh-globe-line);
  display: flex; justify-content: space-between; color: var(--bkh-globe-mute);
  & b { color: var(--bkh-globe-arc); font: 600 13px/1 var(--bkh-globe-mono); font-variant-numeric: tabular-nums; }
}

@container bkh-globe (min-width: 640px) {
  .bkh-globe__nav { display: flex; margin-inline-start: 18px; }
}
@container bkh-globe (min-width: 640px) and (max-width: 939px) {
  .bkh-globe__viz { grid-template-columns: minmax(0, 1fr) minmax(250px, 300px); align-items: center; column-gap: 20px; }
  .bkh-globe__hint { left: 0; right: auto; }
}
@container bkh-globe (min-width: 940px) {
  .bkh-globe__in {
    grid-template-columns: minmax(0, .95fr) minmax(0, 1.05fr);
    grid-template-areas: "bar bar" "copy viz";
    column-gap: 20px;
  }
  .bkh-globe__viz { display: block; margin-block: -20px -30px; margin-inline-end: -20px; }
  .bkh-globe__readout { position: absolute; right: 20px; bottom: 20px; width: min(320px, 70%); }
  .bkh-globe__hint { top: auto; right: auto; left: 8%; bottom: 34px; }
}

@media (prefers-reduced-motion: reduce) {
  .bkh-globe__row, .bkh-globe__meter i { transition: none; @starting-style { opacity: 1; translate: none; width: var(--w); } }
  .bkh-globe__btn, .bkh-globe__btn svg { transition: none; }
}

