  }
}

// Atmosphere, body and rim never change between frames: paint them once per resize
// (the glow uses shadowBlur, far too costly to repeat at 60 fps) and blit each frame.
const body = document.createElement("canvas");
function paintBody() {
  body.width = cv.width; body.height = cv.height;
  const b = body.getContext("2d");
  if (!b) return;
  b.setTransform(dpr, 0, 0, dpr, 0, 0);
  b.save();
  b.shadowColor = col.arc; b.shadowBlur = R * 0.2;
  b.globalAlpha = 0.32; b.fillStyle = col.bg;
  b.beginPath(); b.arc(cx, cy, R, 0, 6.2832); b.fill();
  b.restore();
  b.fillStyle = col.bg;
  b.beginPath(); b.arc(cx, cy, R, 0, 6.2832); b.fill();
  const g = b.createRadialGradient(cx - R * 0.4, cy - R * 0.45, R * 0.05, cx, cy, R * 1.05);
  g.addColorStop(0, col.land); g.addColorStop(1, col.bg);
  b.globalAlpha = 0.14; b.fillStyle = g;
  b.beginPath(); b.arc(cx, cy, R, 0, 6.2832); b.fill();
  b.globalAlpha = 0.3; b.strokeStyle = col.land; b.lineWidth = 1;
  b.beginPath(); b.arc(cx, cy, R, 0, 6.2832); b.stroke();
}

let cY = 1, sY = 0, cP = 1, sP = 0;
function rot(x, y, z, out) {
  const x1 = x * cY + z * sY, z1 = -x * sY + z * cY;
  out[0] = cx + x1 * R;
  out[1] = cy - (y * cP - z1 * sP) * R;
  out[2] = y * sP + z1 * cP;
  out[3] = x1 * x1 + (y * cP - z1 * sP) ** 2; // squared distance from the disc centre, in radii
}
const tmp = [0, 0, 0, 0], tmp2 = [0, 0, 0, 0];

function render() {
  cY = Math.cos(yaw); sY = Math.sin(yaw); cP = Math.cos(pitch); sP = Math.sin(pitch);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, W, H);

  ctx.drawImage(body, 0, 0, W, H);

  // dots, bucketed by depth so each bucket is one path and one fill
  const B = 4, paths = [];
  for (let b = 0; b < B; b++) paths.push(new Path2D());
  const ocean = new Path2D();
  const s = Math.max(0.7, R / 210);
  for (let i = 0; i < N; i++) {
    const x = PX[i], y = PY[i], z = PZ[i];
    const x1 = x * cY + z * sY, z1 = -x * sY + z * cY;
    const z2 = y * sP + z1 * cP;
    if (z2 <= 0.02) continue;
    const sx = cx + x1 * R, sy = cy - (y * cP - z1 * sP) * R;
    if (PL[i]) {
      const r = (0.55 + z2 * 0.85) * s;
      const p = paths[Math.min(B - 1, (z2 * B) | 0)];
      p.moveTo(sx + r, sy); p.arc(sx, sy, r, 0, 6.2832);
    } else if ((i & 1) === 0) {
      ocean.rect(sx - 0.45 * s, sy - 0.45 * s, 0.9 * s, 0.9 * s);
    }
  }
  ctx.fillStyle = col.land;
  ctx.globalAlpha = 0.16; ctx.fill(ocean);
  for (let b = 0; b < B; b++) { ctx.globalAlpha = 0.28 + b * 0.24; ctx.fill(paths[b]); }

  // regions
  ctx.lineWidth = 1; ctx.strokeStyle = col.arc;
  for (const v of EV) {
    rot(v[0], v[1], v[2], tmp);
    if (tmp[2] <= 0.05) continue;
    ctx.globalAlpha = 0.25 + tmp[2] * 0.4;
    ctx.beginPath(); ctx.arc(tmp[0], tmp[1], 2.2 * s, 0, 6.2832); ctx.stroke();
  }

  // routes
  ctx.lineCap = "round";
  routes.forEach((rt, n) => {
    const pts = rt.pts, S = pts.length / 3 - 1;
    const vis = (k) => { rot(pts[k * 3], pts[k * 3 + 1], pts[k * 3 + 2], tmp); return tmp[2] > 0 || tmp[3] > 1; };
    // faint full path
    ctx.globalAlpha = reduce ? 0.75 : 0.2; ctx.strokeStyle = col.arc; ctx.lineWidth = reduce ? 1.5 : 1;
    ctx.beginPath();
    let pen = false;
    for (let k = 0; k <= S; k++) {
      if (vis(k)) { if (pen) ctx.lineTo(tmp[0], tmp[1]); else ctx.moveTo(tmp[0], tmp[1]); pen = true; } else pen = false;
    }
    ctx.stroke();
    if (reduce) return;
    // travelling comet
    const ph = (time * 0.38 + n * 0.23) % 1.55;
    const head = Math.min(1, ph), tail = Math.max(0, ph - 0.42);
    if (tail < 1) {
      const k0 = Math.floor(tail * S), k1 = Math.ceil(head * S);
      for (let k = k0; k < k1; k++) {
        if (!vis(k)) continue;
        const ax = tmp[0], ay = tmp[1];
        if (!vis(k + 1)) continue;
        ctx.globalAlpha = Math.max(0, (k - k0) / Math.max(1, k1 - k0));
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(tmp[0], tmp[1]); ctx.stroke();
      }
      if (ph < 1 && vis(k1)) {
        ctx.fillStyle = col.arc;
        ctx.globalAlpha = 0.25; ctx.beginPath(); ctx.arc(tmp[0], tmp[1], 5.5, 0, 6.2832); ctx.fill();
        ctx.globalAlpha = 1; ctx.beginPath(); ctx.arc(tmp[0], tmp[1], 2.2, 0, 6.2832); ctx.fill();
      }
    }
    if (ph >= 1) { // arrival ripple
      const v = CV[rt.i];
      rot(v[0], v[1], v[2], tmp2);
      if (tmp2[2] > 0) {
        const q = (ph - 1) / 0.55;
        ctx.globalAlpha = 1 - q; ctx.lineWidth = 1.5;
        ctx.beginPath(); ctx.arc(tmp2[0], tmp2[1], 3 + q * 14, 0, 6.2832); ctx.stroke();
      }
    }
  });

  // cities + labels
  ctx.font = "600 10.5px ui-monospace, Menlo, monospace";
  ctx.textBaseline = "middle";
  CITIES.forEach((c, i) => {
    const v = CV[i];
    rot(v[0], v[1], v[2], tmp);
    if (tmp[2] <= 0.04) return;
    const isP = i === primary;
    ctx.globalAlpha = Math.min(1, tmp[2] * 2);
    ctx.fillStyle = isP ? col.arc : col.ink;
    ctx.beginPath(); ctx.arc(tmp[0], tmp[1], isP ? 3.6 : 2.6, 0, 6.2832); ctx.fill();
    if (isP && !reduce) {
      for (let k = 0; k < 2; k++) {
        const q = (time * 0.7 + k * 0.5) % 1;
        ctx.globalAlpha = (1 - q) * 0.8; ctx.strokeStyle = col.arc; ctx.lineWidth = 1.2;
        ctx.beginPath(); ctx.arc(tmp[0], tmp[1], 4 + q * 18, 0, 6.2832); ctx.stroke();
      }
    }
    ctx.globalAlpha = Math.min(1, tmp[2] * 2) * (isP ? 1 : 0.75);
    ctx.fillStyle = isP ? col.arc : col.ink;
    ctx.fillText(c.code, tmp[0] + 8, tmp[1] - 8);
  });
  ctx.globalAlpha = 1;
}

// ---- motion ----
const wrap = (a) => Math.atan2(Math.sin(a), Math.cos(a));
let dragging = false, lastX = 0, lastY = 0, lastT = 0;
let raf = 0, running = false, visible = false, disposed = false, prev = 0;
function frame(now) {
  if (!root.isConnected) return dispose();
  if (!visible || document.hidden) { running = false; return; }
  const dt = Math.min(0.05, (now - prev) / 1000 || 0.016);
  prev = now; time += dt; modeT += dt;
  if (mode === "spin") {
    yaw += 0.075 * dt;
    pitch += (0.42 - pitch) * (1 - Math.exp(-dt * 1.2));
  } else if (mode === "focus") {
    const K = 30, C = 10.5;
    vYaw += (wrap(tgtYaw - yaw) * K - vYaw * C) * dt; yaw += vYaw * dt;
    vPitch += ((tgtPitch - pitch) * K - vPitch * C) * dt; pitch += vPitch * dt;
    if (modeT > 7) { mode = "spin"; modeT = 0; }
  } else if (mode === "coast" && !dragging) {
    vYaw *= Math.exp(-dt * 2.2); yaw += vYaw * dt;
    if (modeT > 2.4) { mode = "spin"; modeT = 0; }
  }
  render();
  raf = requestAnimationFrame(frame);
}
function start() {
  if (running || disposed || reduce || !W) return;
  running = true; prev = performance.now();
  raf = requestAnimationFrame(frame);
}

function select(i) {
  primary = i;
  buildRoutes(); renderReadout();
  tgtYaw = -CITIES[i].lon * D - 0.35;
  tgtPitch = Math.max(-0.45, Math.min(0.62, CITIES[i].lat * D * 0.75));
  if (reduce) { yaw = tgtYaw; pitch = tgtPitch; render(); return; }
  vYaw = 0; vPitch = 0; mode = "focus"; modeT = 0; time = 0;
  if (!running) render();
}
root.querySelector(".bkh-globe__pick").addEventListener("change", (e) => {
  const i = parseInt(e.target.value, 10);
  if (CITIES[i]) select(i);
});

cv.addEventListener("pointerdown", (e) => {
  dragging = true; mode = "drag"; modeT = 0;
  lastX = e.clientX; lastY = e.clientY; lastT = performance.now(); vYaw = 0;
  cv.setPointerCapture(e.pointerId);
  root.classList.add("is-dragged");
});
cv.addEventListener("pointermove", (e) => {
  if (!dragging) return;
  const now = performance.now(), dx = e.clientX - lastX, dy = e.clientY - lastY;
  const k = 2.6 / Math.max(120, R * 2);
  yaw += dx * k * 1.2;
  pitch = Math.max(-0.75, Math.min(0.85, pitch + dy * k));
  vYaw = (dx * k * 1.2) / Math.max(0.008, (now - lastT) / 1000);
  lastX = e.clientX; lastY = e.clientY; lastT = now;
  if (!running) render();
});
const release = () => { if (!dragging) return; dragging = false; mode = "coast"; modeT = 0; };
cv.addEventListener("pointerup", release);
cv.addEventListener("pointercancel", release);

const ro = new ResizeObserver(() => {
  dpr = Math.min(2, window.devicePixelRatio || 1);
  W = cv.clientWidth; H = cv.clientHeight;
  if (!W || !H) return;
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  R = Math.min(W, H) * 0.42; cx = W / 2; cy = H / 2;
  readColours();
  paintBody();
  render();
  if (visible) start();
});
ro.observe(cv);

const io = new IntersectionObserver((es) => {
  visible = es[es.length - 1].isIntersecting;
  if (visible) start();
}, { rootMargin: "60px" });
io.observe(root);
const beat = setInterval(() => {
  if (!root.isConnected) return dispose();
}, 1500);
function dispose() {
  if (disposed) return;
  disposed = true; running = false;
  cancelAnimationFrame(raf); clearInterval(beat); io.disconnect(); ro.disconnect();
}

buildRoutes(); renderReadout();
if (reduce) { tgtYaw = yaw = -CITIES[0].lon * D - 0.35; pitch = 0.5; }

css:
/* Tracewell — a polished hero with its own spec sheet underneath, revealed by a lens.
   The spec layer is a clone of the page, recoloured only (never re-measured), so it
   lines up to the pixel; its redlines are measured live from the base layout.
   Re-theme: --bkh-xray-paper, -ink, -accent (polished) and -red, -graph (spec). */
@property --bkh-xray-r { syntax: "<length>"; inherits: true; initial-value: 120px; }

.bkh-xray {
  --bkh-xray-paper: oklch(0.966 0.016 82);
  --bkh-xray-ink: oklch(0.21 0.02 55);
  --bkh-xray-accent: oklch(0.58 0.15 42);
  --bkh-xray-red: oklch(0.67 0.23 355);
  --bkh-xray-graph: oklch(0.235 0.012 60);
  --bkh-xray-mute: color-mix(in oklch, var(--bkh-xray-ink) 60%, var(--bkh-xray-paper));
  --bkh-xray-line: color-mix(in oklch, var(--bkh-xray-ink) 12%, transparent);
  --bkh-xray-sink: color-mix(in oklch, var(--bkh-xray-paper) 70%, var(--bkh-xray-graph));
  --bkh-xray-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bkh-xray-ease: cubic-bezier(.22, 1, .36, 1);

  container-type: inline-size;
  container-name: bkh-xray;
  position: relative; isolation: isolate; overflow: hidden;
  width: 100%;
  border-radius: 18px;
  background: var(--bkh-xray-paper);
  color: var(--bkh-xray-ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  & :where(a) { color: inherit; text-decoration: none; }
  & :focus-visible { outline: 2px solid var(--bkh-xray-accent); outline-offset: 3px; border-radius: 8px; }
}
.bkh-xray__stage {
  --bkh-xray-x: 640px; --bkh-xray-y: 240px;
  --bkh-xray-r: clamp(84px, 13cqi, 150px);
  position: relative;
  transition: --bkh-xray-r .5s var(--bkh-xray-ease);
}
.bkh-xray__stage:active { --bkh-xray-r: clamp(110px, 17cqi, 200px); }
.bkh-xray[data-all] .bkh-xray__stage { --bkh-xray-r: 2400px; transition-duration: 1.1s; }

/* ---------- polished page ---------- */
.bkh-xray__page {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "bar" "copy" "shot";
  gap: 34px;
  padding: clamp(16px, 4.4cqi, 52px) clamp(16px, 4.4cqi, 52px) clamp(64px, 7cqi, 72px);
}
.bkh-xray__bar { grid-area: bar; display: flex; align-items: center; gap: 22px; font-size: 14px; }
.bkh-xray__logo {
  display: inline-flex; align-items: center; gap: 8px; font-weight: 750; font-size: 17px; letter-spacing: -.03em;
  & svg { width: 24px; height: 24px; fill: none; stroke: var(--bkh-xray-accent); stroke-width: 2; stroke-linecap: round; }
}
.bkh-xray__nav { display: none; gap: 22px; color: var(--bkh-xray-mute); & a:hover { color: var(--bkh-xray-ink); } }
.bkh-xray__in { margin-inline-start: auto; font-weight: 600; }

.bkh-xray__copy { grid-area: copy; align-self: center; }
.bkh-xray__eyebrow {
  margin: 0 0 18px; font: 600 11.5px/1 var(--bkh-xray-mono); letter-spacing: .14em; text-transform: uppercase; color: var(--bkh-xray-accent);
}
.bkh-xray__title {
  margin: 0; max-width: 13ch;
  font-size: clamp(2.3rem, .9rem + 5.6cqi, 5rem); line-height: .98; letter-spacing: -.05em; font-weight: 800;
  text-wrap: balance;
}
.bkh-xray__lede { margin: 22px 0 0; max-width: 44ch; font-size: clamp(15px, 13.5px + .4cqi, 17.5px); line-height: 1.6; color: var(--bkh-xray-mute); text-wrap: pretty; }
.bkh-xray__cta { margin-top: 28px; display: flex; flex-wrap: wrap; gap: 12px; width: fit-content; }
.bkh-xray__btn {
  display: inline-flex; align-items: center; height: 46px; padding: 0 20px; border-radius: 12px;
  background: var(--bkh-xray-ink); color: var(--bkh-xray-paper); font-weight: 650; font-size: 14.5px;
  transition: background .25s, translate .25s var(--bkh-xray-ease);
  &:hover { background: var(--bkh-xray-accent); translate: 0 -1px; }
}
.bkh-xray__btn--q { background: transparent; color: var(--bkh-xray-ink); box-shadow: inset 0 0 0 1.5px var(--bkh-xray-line); &:hover { background: color-mix(in oklch, var(--bkh-xray-ink) 6%, transparent); } }

.bkh-xray__shot { grid-area: shot; margin: 0; align-self: center; min-width: 0; }
.bkh-xray__win {
  display: grid; grid-template-columns: minmax(0, 1fr) 132px;
  border-radius: 16px; overflow: hidden;
  background: color-mix(in oklch, var(--bkh-xray-paper), white 60%);
  box-shadow: 0 0 0 1px var(--bkh-xray-line), 0 30px 60px -32px color-mix(in oklch, var(--bkh-xray-ink) 45%, transparent);
}
.bkh-xray__canvas {
  display: grid; place-items: center; padding: 28px 18px;
  background: radial-gradient(circle, color-mix(in oklch, var(--bkh-xray-ink) 14%, transparent) 1px, transparent 1.5px) 0 0 / 16px 16px, color-mix(in oklch, var(--bkh-xray-paper), var(--bkh-xray-ink) 3%);
}
.bkh-xray__card {
  width: min(100%, 220px); padding: 20px 20px 18px; border-radius: 12px;
  background: color-mix(in oklch, var(--bkh-xray-paper), white 75%);
  box-shadow: 0 1px 2px var(--bkh-xray-line), 0 12px 24px -16px color-mix(in oklch, var(--bkh-xray-ink) 40%, transparent);
  display: grid; gap: 14px;
}
.bkh-xray__plan { margin: 0; font: 600 11px/1 var(--bkh-xray-mono); letter-spacing: .1em; text-transform: uppercase; color: var(--bkh-xray-accent); }
.bkh-xray__price { margin: 0; display: flex; align-items: baseline; gap: 6px; & b { font-size: 34px; letter-spacing: -.04em; font-variant-numeric: tabular-nums; } & span { font-size: 12px; color: var(--bkh-xray-mute); } }
.bkh-xray__feat { list-style: none; margin: 0; padding: 0; display: grid; gap: 7px; font-size: 13px;
  & li { display: flex; align-items: center; gap: 8px; }
  & li::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--bkh-xray-accent); }
}
.bkh-xray__cardbtn { display: grid; place-items: center; height: 38px; border-radius: 9px; background: var(--bkh-xray-ink); color: var(--bkh-xray-paper); font-weight: 600; font-size: 13px; }
.bkh-xray__insp {
  padding: 14px 12px; border-inline-start: 1px solid var(--bkh-xray-line); font-size: 11px;
  & p { margin: 0 0 10px; font-weight: 700; font-size: 11.5px; }
  & dl { margin: 0; display: grid; gap: 9px; }
  & dt { color: var(--bkh-xray-mute); font-size: 10px; }
  & dd { margin: 2px 0 0; font: 500 11px/1.2 var(--bkh-xray-mono); }
}
.bkh-xray__shot figcaption { margin-top: 12px; font-size: 12.5px; color: var(--bkh-xray-mute); text-wrap: pretty; }

/* ---------- the spec layer: same boxes, recoloured, masked to the lens ---------- */
.bkh-xray__spec {
  position: absolute; inset: 0; z-index: 2; pointer-events: none;
  background:
    linear-gradient(color-mix(in oklch, white 3.5%, transparent) 1px, transparent 1px) 0 0 / 100% 8px,
    var(--bkh-xray-graph);
  color: color-mix(in oklch, white 82%, var(--bkh-xray-graph));
  -webkit-mask-image: radial-gradient(circle at var(--bkh-xray-x) var(--bkh-xray-y), #000 var(--bkh-xray-r), transparent calc(var(--bkh-xray-r) + 1px));
  mask-image: radial-gradient(circle at var(--bkh-xray-x) var(--bkh-xray-y), #000 var(--bkh-xray-r), transparent calc(var(--bkh-xray-r) + 1px));
  & .bkh-xray__page { position: relative; z-index: 1; }
  & .bkh-xray__page :is(a, p, h1, b, span, li, dt, dd, figcaption) { color: inherit; }
  & .bkh-xray__page svg { stroke: var(--bkh-xray-red); }
  & .bkh-xray__eyebrow, & .bkh-xray__plan { color: var(--bkh-xray-red); }
  & :is(.bkh-xray__btn, .bkh-xray__cardbtn) { background: transparent; box-shadow: inset 0 0 0 1px var(--bkh-xray-red); color: inherit; }
  & :is(.bkh-xray__win, .bkh-xray__card) { background: transparent; box-shadow: 0 0 0 1px color-mix(in oklch, white 30%, transparent); }
  & .bkh-xray__canvas { background: transparent; }
  & .bkh-xray__insp { border-color: color-mix(in oklch, white 22%, transparent); }
  & .bkh-xray__feat li::before { background: var(--bkh-xray-red); }
}
.bkh-xray__cols {
  position: absolute; inset: 0; z-index: 0;
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px;
  padding-inline: clamp(16px, 4.4cqi, 52px);
  & i { background: color-mix(in oklch, var(--bkh-xray-red) 9%, transparent); border-inline: 1px solid color-mix(in oklch, var(--bkh-xray-red) 22%, transparent); }
  & i:nth-child(n + 5) { display: none; }
}
.bkh-xray__marks { position: absolute; inset: 0; z-index: 2; font: 600 10px/1 var(--bkh-xray-mono); font-variant-numeric: tabular-nums; }
.bkh-xray__box {
  position: absolute; outline: 1px dashed color-mix(in oklch, var(--bkh-xray-red) 85%, transparent); outline-offset: 0;
  & span { position: absolute; left: -1px; bottom: 100%; margin-bottom: 3px; padding: 3px 5px; border-radius: 3px; white-space: nowrap; background: var(--bkh-xray-red); color: white; }
}
.bkh-xray__gap, .bkh-xray__pad {
  position: absolute; display: grid; place-items: center;
  & span { padding: 2px 4px; border-radius: 3px; background: var(--bkh-xray-graph); color: var(--bkh-xray-red); box-shadow: 0 0 0 1px var(--bkh-xray-red); }
}
.bkh-xray__gap { border-inline: 0; background: linear-gradient(var(--bkh-xray-red), var(--bkh-xray-red)) 50% 0 / 1px 100% no-repeat;
  &::before, &::after { content: ""; position: absolute; left: calc(50% - 5px); width: 10px; height: 1px; background: var(--bkh-xray-red); }
  &::before { top: 0; } &::after { bottom: 0; }
}
.bkh-xray__pad { background: linear-gradient(var(--bkh-xray-red), var(--bkh-xray-red)) 0 50% / 100% 1px no-repeat;
  &::before, &::after { content: ""; position: absolute; top: calc(50% - 5px); width: 1px; height: 10px; background: var(--bkh-xray-red); }
  &::before { left: 0; } &::after { right: 0; }
}

/* the lens rim */
.bkh-xray__ring {
  position: absolute; left: 0; top: 0; z-index: 3; pointer-events: none;
  width: calc(var(--bkh-xray-r) * 2); aspect-ratio: 1;
  translate: calc(var(--bkh-xray-x) - var(--bkh-xray-r)) calc(var(--bkh-xray-y) - var(--bkh-xray-r));
  border-radius: 50%;
  box-shadow: 0 0 0 1.5px var(--bkh-xray-red), 0 0 0 6px color-mix(in oklch, var(--bkh-xray-red) 14%, transparent), 0 24px 50px -20px color-mix(in oklch, var(--bkh-xray-graph) 70%, transparent);
  & span {
    position: absolute; left: 50%; top: 100%; translate: -50% 10px;
    padding: 4px 8px; border-radius: 999px; white-space: nowrap;
    background: var(--bkh-xray-red); color: white; font: 600 10px/1 var(--bkh-xray-mono); letter-spacing: .06em; text-transform: uppercase;
  }
}
.bkh-xray[data-all] .bkh-xray__ring { opacity: 0; transition: opacity .3s; }

.bkh-xray__all {
  position: absolute; right: clamp(12px, 2.4cqi, 24px); bottom: clamp(12px, 2.4cqi, 22px); z-index: 4;
  display: inline-flex; align-items: center; gap: 8px; cursor: pointer;
  padding: 9px 14px 9px 11px; border-radius: 999px; border: 0;
  background: var(--bkh-xray-graph); color: white; font: 600 12.5px/1 system-ui, sans-serif;
  box-shadow: 0 10px 24px -12px var(--bkh-xray-graph);
  transition: background .25s, translate .25s var(--bkh-xray-ease);
  & svg { width: 16px; height: 16px; fill: none; stroke: var(--bkh-xray-red); stroke-width: 2; stroke-linecap: round; transition: rotate .6s var(--bkh-xray-ease); }
  &:hover { translate: 0 -1px; }
  &[aria-pressed="true"] { background: var(--bkh-xray-red); }
  &[aria-pressed="true"] svg { stroke: white; rotate: 90deg; }
  &:focus-visible { outline-color: var(--bkh-xray-red); }
}

@container bkh-xray (min-width: 600px) {
  .bkh-xray__nav { display: flex; margin-inline-start: 18px; }
  .bkh-xray__cols { grid-template-columns: repeat(8, 1fr); gap: 20px; }
  .bkh-xray__cols i:nth-child(n + 5) { display: block; }
  .bkh-xray__cols i:nth-child(n + 9) { display: none; }
  .bkh-xray__win { grid-template-columns: minmax(0, 1fr) 160px; }
}
@container bkh-xray (min-width: 900px) {
  .bkh-xray__page {
    grid-template-columns: minmax(0, 1.1fr) minmax(0, .9fr);
    grid-template-areas: "bar bar" "copy shot";
    column-gap: 48px; row-gap: 44px;
  }
  .bkh-xray__cols { grid-template-columns: repeat(12, 1fr); gap: 24px; }
  .bkh-xray__cols i:nth-child(n + 9) { display: block; }
}

@media (prefers-reduced-motion: reduce) {
  .bkh-xray__stage, .bkh-xray[data-all] .bkh-xray__stage { transition: none; }
  .bkh-xray__btn, .bkh-xray__all, .bkh-xray__all svg, .bkh-xray[data-all] .bkh-xray__ring { transition: none; }
}

