// Spec lens. The page is cloned once into the spec layer (same classes, so the same
// layout — only colours change there). Redlines are measured from the live base layout
// on every resize, so the numbers in the lens are the real ones. The lens itself is a
// radial mask driven by two custom properties; its radius is a registered <length>,
// which is what lets "Show all specs" transition it.
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
const stage = root.querySelector(".bkh-xray__stage");
const page = root.querySelector(".bkh-xray__page");
const spec = root.querySelector(".bkh-xray__spec");
const marks = root.querySelector(".bkh-xray__marks");
const cols = root.querySelector(".bkh-xray__cols");
const btn = root.querySelector(".bkh-xray__all");
const label = btn.querySelector("span");

const clone = page.cloneNode(true);
clone.querySelectorAll("[aria-label]").forEach((n) => n.removeAttribute("aria-label"));
clone.querySelectorAll("a").forEach((a) => a.removeAttribute("href"));
spec.prepend(clone);
for (let i = 0; i < 12; i++) cols.append(document.createElement("i"));

const round = (v) => Math.round(parseFloat(v));
const LABELS = {
  nav: (el, r) => "Nav · " + Math.round(r.height) + "h",
  eyebrow: (el, r, cs) => "Eyebrow · " + round(cs.fontSize) + "px · +" + (parseFloat(cs.letterSpacing) / parseFloat(cs.fontSize)).toFixed(2) + "em",
  h1: (el, r, cs) => "H1 · " + round(cs.fontSize) + "/" + round(cs.lineHeight) + " · " + cs.fontWeight,
  body: (el, r, cs) => "Body · " + round(cs.fontSize) + "/" + round(cs.lineHeight) + " · " + Math.round(r.width) + "w",
  cta: (el) => {
    const bc = getComputedStyle(el.querySelector(".bkh-xray__btn"));
    return "Button · " + round(bc.height) + "h · r" + round(bc.borderTopLeftRadius);
  },
  frame: (el, r) => "Frame · " + Math.round(r.width) + "×" + Math.round(r.height)
};
function mark(cls, x, y, w, h, text) {
  const d = document.createElement("div");
  d.className = cls;
  d.style.cssText = "left:" + x.toFixed(1) + "px;top:" + y.toFixed(1) + "px;width:" + w.toFixed(1) + "px;height:" + h.toFixed(1) + "px";
  const s = document.createElement("span");
  s.textContent = text;
  d.append(s);
  return d;
}
function measure() {
  if (!root.isConnected) return;
  const sr = stage.getBoundingClientRect();
  const out = [];
  page.querySelectorAll("[data-spec]").forEach((el) => {
    const r = el.getBoundingClientRect();
    if (!r.width) return;
    out.push(mark("bkh-xray__box", r.left - sr.left, r.top - sr.top, r.width, r.height, LABELS[el.dataset.spec](el, r, getComputedStyle(el))));
  });
  // vertical rhythm between the copy blocks
  const kids = Array.from(page.querySelector(".bkh-xray__copy").children);
  for (let i = 0; i < kids.length - 1; i++) {
    const a = kids[i].getBoundingClientRect(), b = kids[i + 1].getBoundingClientRect();
    const gap = b.top - a.bottom;
    if (gap < 8) continue;
    const x = a.left - sr.left + Math.min(a.width, b.width) * 0.66;
    out.push(mark("bkh-xray__gap", x - 16, a.bottom - sr.top, 32, gap, String(Math.round(gap))));
  }
  // page gutter, measured at the headline
  const title = page.querySelector(".bkh-xray__title").getBoundingClientRect();
  const gutter = title.left - sr.left;
  out.push(mark("bkh-xray__pad", 0, title.top - sr.top + title.height / 2 - 12, gutter, 24, String(Math.round(gutter))));
  // gap between copy and frame on wide layouts
  const shot = page.querySelector(".bkh-xray__shot").getBoundingClientRect();
  const copy = page.querySelector(".bkh-xray__copy").getBoundingClientRect();
  if (shot.left > copy.right + 8) {
    out.push(mark("bkh-xray__pad", copy.right - sr.left, shot.top - sr.top + 40, shot.left - copy.right, 24, String(Math.round(shot.left - copy.right))));
  }
  marks.replaceChildren(...out);
}

// ---- lens ----
let W = 1, H = 1, x = 0, y = 0, tx = 0, ty = 0, hover = false, t = 0;
let raf = 0, last = 0, running = false, visible = false, disposed = false, queued = false;
function place() {
  stage.style.setProperty("--bkh-xray-x", x.toFixed(1) + "px");
  stage.style.setProperty("--bkh-xray-y", y.toFixed(1) + "px");
}
function idleTarget() {
  tx = W * (0.56 + 0.3 * Math.cos(t * 0.33));
  ty = H * (0.44 + 0.24 * Math.sin(t * 0.52));
}
function frame(now) {
  if (!root.isConnected) return dispose();
  if (!visible || document.hidden) { running = false; return; }
  const dt = Math.min(0.05, (now - last) / 1000 || 0.016);
  last = now; t += dt;
  if (!hover) idleTarget();
  const k = 1 - Math.exp(-dt * (hover ? 14 : 1.6));
  x += (tx - x) * k; y += (ty - y) * k;
  place();
  raf = requestAnimationFrame(frame);
}
function start() {
  if (running || disposed || reduce) return;
  running = true; last = performance.now();
  raf = requestAnimationFrame(frame);
}

const ro = new ResizeObserver(() => {
  const first = W === 1;
  W = stage.clientWidth || 1; H = stage.clientHeight || 1;
  if (first) { t = 0; idleTarget(); x = tx; y = ty; place(); }
  if (!queued) {
    queued = true;
    requestAnimationFrame(() => { if (!root.isConnected) return; queued = false; measure(); });
  }
});
ro.observe(stage);

stage.addEventListener("pointermove", (e) => {
  const r = stage.getBoundingClientRect();
  tx = e.clientX - r.left; ty = e.clientY - r.top; hover = true;
  if (reduce) { x = tx; y = ty; place(); }
});
stage.addEventListener("pointerdown", (e) => {
  const r = stage.getBoundingClientRect();
  tx = e.clientX - r.left; ty = e.clientY - r.top; hover = true;
  if (reduce) { x = tx; y = ty; place(); }
});
stage.addEventListener("pointerleave", () => { hover = false; });

btn.addEventListener("click", () => {
  const on = !root.hasAttribute("data-all");
  root.toggleAttribute("data-all", on);
  btn.setAttribute("aria-pressed", String(on));
  label.textContent = on ? "Hide specs" : "Show all specs";
});
root.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && root.hasAttribute("data-all")) btn.click();
});

const io = new IntersectionObserver((es) => {
  visible = es[es.length - 1].isIntersecting;
  if (visible) start();
}, { rootMargin: "60px" });
io.observe(root);
const beat = setInterval(() => {
  if (!root.isConnected) return dispose();
}, 1500);
function dispose() {
  if (disposed) return;
  disposed = true; running = false;
  cancelAnimationFrame(raf); clearInterval(beat); io.disconnect(); ro.disconnect();
}

css:
/* Puddle — metaball ideas: every pill is two circles under an SVG goo filter
   (blur + alpha threshold), each circle on its own spring, so pills stretch and
   merge like liquid. Re-theme: --bkh-goo-bg, -ink, -cream. */
.bkh-goo {
  --bkh-goo-bg: oklch(0.78 0.155 58);
  --bkh-goo-ink: oklch(0.22 0.045 40);
  --bkh-goo-cream: oklch(0.975 0.03 92);
  --bkh-goo-board: color-mix(in oklch, var(--bkh-goo-bg), var(--bkh-goo-ink) 9%);
  --bkh-goo-soft: color-mix(in oklch, var(--bkh-goo-ink) 72%, var(--bkh-goo-bg));
  --bkh-goo-bounce: cubic-bezier(.34, 1.56, .64, 1);
  --bkh-goo-ease: cubic-bezier(.22, 1, .36, 1);

  container-type: inline-size;
  container-name: bkh-goo;
  position: relative; isolation: isolate; overflow: hidden;
  width: 100%;
  border-radius: 28px;
  background: var(--bkh-goo-bg);
  color: var(--bkh-goo-ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  & :where(a) { color: inherit; text-decoration: none; }
  & :focus-visible { outline: 3px solid var(--bkh-goo-ink); outline-offset: 3px; border-radius: 12px; }
  & feDropShadow { flood-color: var(--bkh-goo-ink); }
}
.bkh-goo__in {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "bar" "copy" "board";
  gap: 28px;
  padding: clamp(16px, 4.2cqi, 48px);
}
.bkh-goo__bar { grid-area: bar; display: flex; align-items: center; gap: 22px; font-size: 14.5px; font-weight: 600; }
.bkh-goo__logo {
  display: inline-flex; align-items: center; gap: 7px; font-weight: 900; font-size: 21px; letter-spacing: -.05em;
  & svg { width: 30px; height: 30px; fill: var(--bkh-goo-cream); stroke: var(--bkh-goo-ink); stroke-width: 1.6; stroke-linejoin: round; }
  & circle { fill: var(--bkh-goo-ink); stroke: none; }
}
.bkh-goo__nav { display: none; gap: 20px; & a { opacity: .78; transition: opacity .2s; } & a:hover { opacity: 1; } }
.bkh-goo__login { margin-inline-start: auto; padding: 8px 16px; border-radius: 999px; background: var(--bkh-goo-cream); transition: scale .3s var(--bkh-goo-bounce); &:hover { scale: 1.06; } }

/* ---- copy ---- */
.bkh-goo__copy { grid-area: copy; align-self: center; }
.bkh-goo__title {
  margin: 0;
  font-size: clamp(2.6rem, .8rem + 7.4cqi, 6rem); line-height: .92; letter-spacing: -.06em; font-weight: 900;
  text-wrap: balance;
}
.bkh-goo__messy {
  position: relative; display: inline-block;
  & svg { position: absolute; left: -2%; bottom: -.1em; width: 104%; height: .26em; overflow: visible; }
  & path { fill: none; stroke: var(--bkh-goo-cream); stroke-width: 5; stroke-linecap: round; vector-effect: non-scaling-stroke;
    stroke-dasharray: 1; stroke-dashoffset: 0; transition: stroke-dashoffset 1.3s var(--bkh-goo-ease) .5s;
    @starting-style { stroke-dashoffset: 1; } }
}
.bkh-goo__lede { margin: 22px 0 0; max-width: 42ch; font-size: clamp(15.5px, 14px + .4cqi, 18.5px); line-height: 1.55; font-weight: 500; color: var(--bkh-goo-soft); text-wrap: pretty; }
.bkh-goo__cta { margin-top: 28px; display: flex; flex-wrap: wrap; align-items: center; gap: 14px 22px; }
.bkh-goo__btn {
  padding: 16px 24px; border-radius: 999px;
  background: var(--bkh-goo-ink); color: var(--bkh-goo-cream); font-weight: 800; font-size: 15.5px;
  transition: scale .45s var(--bkh-goo-bounce), rotate .45s var(--bkh-goo-bounce);
  &:hover { scale: 1.05; rotate: -2deg; }
  &:active { scale: .96; }
}
.bkh-goo__link { font-weight: 750; font-size: 15px; text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: 5px; text-decoration-color: color-mix(in oklch, var(--bkh-goo-ink) 35%, transparent); transition: text-decoration-color .2s; &:hover { text-decoration-color: var(--bkh-goo-ink); } }
.bkh-goo__proof { margin-top: 26px; display: flex; align-items: center; gap: 12px; font-size: 13.5px; font-weight: 600; color: var(--bkh-goo-soft); }
.bkh-goo__faces { display: inline-flex;
  & i { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; font-style: normal; font-size: 10.5px; font-weight: 800; background: var(--bkh-goo-cream); color: var(--bkh-goo-ink); border: 2px solid var(--bkh-goo-bg); }
  & i + i { margin-inline-start: -9px; }
  & i:nth-child(2) { background: var(--bkh-goo-ink); color: var(--bkh-goo-cream); }
  & i:last-child { background: color-mix(in oklch, var(--bkh-goo-cream) 60%, var(--bkh-goo-bg)); }
}

/* ---- board ---- */
.bkh-goo__board {
  grid-area: board; position: relative; min-width: 0;
  display: grid; grid-template-rows: auto 1fr auto;
  border-radius: 22px;
  background: var(--bkh-goo-board);
  box-shadow: inset 0 0 0 2px color-mix(in oklch, var(--bkh-goo-ink) 12%, transparent);
}
.bkh-goo__tools { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 12px 12px 0 16px; font-size: 13px; font-weight: 600; }
.bkh-goo__count b { font-variant-numeric: tabular-nums; }
.bkh-goo__merge {
  display: inline-flex; align-items: center; gap: 7px; cursor: pointer;
  padding: 9px 14px 9px 11px; border: 0; border-radius: 999px;
  background: var(--bkh-goo-ink); color: var(--bkh-goo-cream); font: 700 13px/1 system-ui, sans-serif;
  transition: scale .4s var(--bkh-goo-bounce), background .25s;
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; transition: rotate .5s var(--bkh-goo-bounce); }
  &:hover { scale: 1.05; }
  &:active { scale: .95; }
  &[aria-pressed="true"] { background: var(--bkh-goo-cream); color: var(--bkh-goo-ink); }
  &[aria-pressed="true"] svg { rotate: 180deg; }
}
.bkh-goo__area {
  position: relative; height: clamp(340px, 46cqi, 470px); margin: 6px;
  border-radius: 16px; overflow: hidden; touch-action: none;
  background: radial-gradient(circle, color-mix(in oklch, var(--bkh-goo-ink) 18%, transparent) 1.2px, transparent 1.6px) 0 0 / 22px 22px;
}
.bkh-goo__svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.bkh-goo__blobs :is(circle, rect) { fill: var(--bkh-goo-cream); }
.bkh-goo__ideas { position: absolute; inset: 0; }
.bkh-goo__idea {
  position: absolute; left: 0; top: 0;
  translate: var(--x, -999px) var(--y, -999px);
  height: 44px; padding: 0 18px; border: 0; background: none; cursor: grab;
  font: 700 14px/44px system-ui, -apple-system, sans-serif; letter-spacing: -.01em; white-space: nowrap; color: var(--bkh-goo-ink);
  touch-action: none; user-select: none; -webkit-user-select: none;
  &:active { cursor: grabbing; }
  &:focus-visible { outline: 2.5px solid var(--bkh-goo-ink); outline-offset: -2px; border-radius: 999px; }
}
.bkh-goo__planhd {
  position: absolute; left: 50%; top: 12px; margin: 0; translate: -50% 0;
  font: 800 12px/1 ui-monospace, Menlo, monospace; letter-spacing: .08em; text-transform: uppercase; white-space: nowrap;
  opacity: 0; scale: .9; transition: opacity .4s, scale .5s var(--bkh-goo-bounce);
}
.bkh-goo.is-merged .bkh-goo__planhd { opacity: 1; scale: 1; transition-delay: .35s; }
.bkh-goo__help { margin: 0; padding: 0 16px 14px; font-size: 12.5px; font-weight: 500; color: var(--bkh-goo-soft); text-wrap: pretty; }
.bkh-goo__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; margin: 0; }

@container bkh-goo (min-width: 600px) {
  .bkh-goo__nav { display: flex; margin-inline-start: 14px; }
}
@container bkh-goo (min-width: 900px) {
  .bkh-goo__in {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    grid-template-areas: "bar bar" "copy board";
    column-gap: 40px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .bkh-goo__messy path { transition: none; @starting-style { stroke-dashoffset: 0; } }
  .bkh-goo__btn, .bkh-goo__login, .bkh-goo__merge, .bkh-goo__merge svg, .bkh-goo__planhd { transition: none; }
}

js:
// Metaballs without WebGL: an SVG filter blurs the circles and thresholds the alpha
// channel (feColorMatrix 0 0 0 24 -10), so overlapping circles fuse with liquid necks.
// Each idea pill is two circles on their own springs trailing one anchor, which is
// why pills stretch when flung. "Merge" stacks the anchors into one column, and the
// filter turns the column into a single puddle with the plan inside it.
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
const uid = Math.random().toString(36).slice(2, 8);
const area = root.querySelector(".bkh-goo__area");
const g = root.querySelector(".bkh-goo__blobs");
const filter = root.querySelector(".bkh-goo__svg filter");
filter.id = "bkh-goo-f-" + uid;
g.setAttribute("filter", "url(#" + filter.id + ")");
const mergeBtn = root.querySelector(".bkh-goo__merge");
const mergeLabel = mergeBtn.querySelector("span");
const countEl = root.querySelector(".bkh-goo__count");
const sr = root.querySelector(".bkh-goo__sr");
const btns = Array.from(root.querySelectorAll(".bkh-goo__idea"));

const PR = 22; // pill radius: half the 44px label height
// Per idea: a capsule body that rides the anchor, plus two softer end circles that lag
// behind it. At rest the circles hide inside the capsule; in motion they pull liquid tails.
g.innerHTML = btns.map(() => '<rect rx="22" ry="22" height="44" width="0"></rect><circle r="0"></circle><circle r="0"></circle>').join("") + '<circle r="0"></circle>';
const shapes = Array.from(g.children);
const cursor = { x: -200, y: -200, vx: 0, vy: 0, r: 0, tr: 0, tx: -200, ty: -200, el: shapes[shapes.length - 1] };

const ideas = btns.map((el, i) => ({
  el, i, hx: parseFloat(el.dataset.x), hy: parseFloat(el.dataset.y),
  x: 0, y: 0, vx: 0, vy: 0, w: 120, delay: 0, drag: false, ox: 0, oy: 0, moved: 0,
  body: shapes[i * 3],
  c: [1, 2].map((k) => ({ x: 0, y: 0, vx: 0, vy: 0, el: shapes[i * 3 + k] }))
}));
let plan = [3, 7, 1, 4, 6, 5, 0, 2]; // merged order, by priority
let merged = false, W = 1, H = 1, t = 0, placed = false;

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
function target(d) {
  if (merged) {
    const n = ideas.length, s = Math.min(40, (H - 64) / n);
    const top = H / 2 - ((n - 1) * s) / 2 + 16;
    return [W / 2, top + plan.indexOf(d.i) * s];
  }
  const wob = reduce ? 0 : 5;
  let tx = d.hx * W + Math.sin(t * 0.8 + d.i * 1.7) * wob;
  let ty = d.hy * H + Math.cos(t * 0.7 + d.i * 1.1) * wob;
  if (cursor.tr > 0) {
    const dx = cursor.tx - tx, dy = cursor.ty - ty, dist = Math.hypot(dx, dy);
    if (dist < 150) { const f = 0.3 * (1 - dist / 150); tx += dx * f; ty += dy * f; }
  }
  return [clamp(tx, d.w / 2 + 4, W - d.w / 2 - 4), clamp(ty, PR + 4, H - PR - 4)];
}
function measure() {
  W = area.clientWidth || 1; H = area.clientHeight || 1;
  ideas.forEach((d) => { d.w = Math.max(PR * 2 + 8, d.el.offsetWidth); });
  if (!placed) {
    placed = true;
    ideas.forEach((d) => {
      const [x, y] = target(d);
      d.x = x; d.y = y;
      d.c.forEach((c, k) => { c.x = x + (k ? 1 : -1) * (d.w / 2 - PR); c.y = y; });
    });
  }
}

function step(dt) {
  t += dt;
  const snap = reduce;
  ideas.forEach((d) => {
    if (!d.drag) {
      if (d.delay > 0) d.delay -= dt;
      else {
        const [tx, ty] = target(d);
        if (snap) { d.x = tx; d.y = ty; d.vx = d.vy = 0; }
        else {
          d.vx += ((tx - d.x) * 55 - d.vx * 9) * dt; d.x += d.vx * dt;
          d.vy += ((ty - d.y) * 55 - d.vy * 9) * dt; d.y += d.vy * dt;
        }
      }
    }
    d.c.forEach((c, k) => {
      const cx = d.x + (k ? 1 : -1) * (d.w / 2 - PR), cy = d.y;
      if (snap) { c.x = cx; c.y = cy; return; }
      c.vx += ((cx - c.x) * 90 - c.vx * 10) * dt; c.x += c.vx * dt;
      c.vy += ((cy - c.y) * 90 - c.vy * 10) * dt; c.y += c.vy * dt;
    });
  });
  if (snap) { cursor.x = cursor.tx; cursor.y = cursor.ty; cursor.r = 0; }
  else {
    cursor.vx += ((cursor.tx - cursor.x) * 260 - cursor.vx * 22) * dt; cursor.x += cursor.vx * dt;
    cursor.vy += ((cursor.ty - cursor.y) * 260 - cursor.vy * 22) * dt; cursor.y += cursor.vy * dt;
    cursor.r += (cursor.tr - cursor.r) * (1 - Math.exp(-dt * 10));
  }
}
function paint() {
  ideas.forEach((d) => {
    const x0 = (d.x - d.w / 2).toFixed(1), y0 = (d.y - PR).toFixed(1);
    d.el.style.setProperty("--x", x0 + "px");
    d.el.style.setProperty("--y", y0 + "px");
    d.body.setAttribute("x", x0);
    d.body.setAttribute("y", y0);
    d.body.setAttribute("width", d.w.toFixed(1));
    d.c.forEach((c) => {
      c.el.setAttribute("cx", c.x.toFixed(1));
      c.el.setAttribute("cy", c.y.toFixed(1));
      c.el.setAttribute("r", PR - 1);
    });
  });
  cursor.el.setAttribute("cx", cursor.x.toFixed(1));
  cursor.el.setAttribute("cy", cursor.y.toFixed(1));
  cursor.el.setAttribute("r", Math.max(0, cursor.r).toFixed(1));
}

let raf = 0, last = 0, running = false, visible = false, disposed = false;
function frame(now) {
  if (!root.isConnected) return dispose();
  if (!visible || document.hidden) { running = false; return; }
  step(Math.min(0.033, (now - last) / 1000 || 0.016));
  last = now;
  paint();
  raf = requestAnimationFrame(frame);
}
function start() {
  if (running || disposed) return;
  if (reduce) { step(0); paint(); return; }
  running = true; last = performance.now();
  raf = requestAnimationFrame(frame);
}
const kick = () => { if (reduce) { step(0); paint(); } else if (visible) start(); };

// ---- cursor blob ----
area.addEventListener("pointermove", (e) => {
  if (e.pointerType === "touch") return;
  const r = area.getBoundingClientRect();
  cursor.tx = e.clientX - r.left; cursor.ty = e.clientY - r.top;
  if (cursor.tr === 0) { cursor.x = cursor.tx; cursor.y = cursor.ty; }
  cursor.tr = ideas.some((d) => d.drag) ? 0 : 24;
});
area.addEventListener("pointerleave", () => { cursor.tr = 0; });

// ---- dragging, flinging, poking ----
function reorderTo(d, rank) {
  plan.splice(plan.indexOf(d.i), 1);
  plan.splice(clamp(rank, 0, plan.length), 0, d.i);
}
ideas.forEach((d) => {
  d.el.addEventListener("pointerdown", (e) => {
    if (e.button !== 0) return;
    const r = area.getBoundingClientRect();
    d.drag = true; d.moved = 0; d.delay = 0;
    d.ox = e.clientX - r.left - d.x; d.oy = e.clientY - r.top - d.y;
    d.el.setPointerCapture(e.pointerId);
    cursor.tr = 0;
  });
  d.el.addEventListener("pointermove", (e) => {
    if (!d.drag) return;
    const r = area.getBoundingClientRect();
    const nx = clamp(e.clientX - r.left - d.ox, d.w / 2 + 4, W - d.w / 2 - 4);
    const ny = clamp(e.clientY - r.top - d.oy, PR + 4, H - PR - 4);
    d.moved += Math.abs(nx - d.x) + Math.abs(ny - d.y);
    d.vx = (nx - d.x) * 30; d.vy = (ny - d.y) * 30;
    d.x = nx; d.y = ny;
    kick();
  });
  const end = () => {
    if (!d.drag) return;
    d.drag = false;
    if (d.moved < 4) {
      // a poke: kick the two halves apart so the pill wobbles
      d.c[0].vx -= 260; d.c[1].vx += 260; d.c[0].vy -= 120; d.c[1].vy += 120;
    } else if (merged) {
      const n = ideas.length, s = Math.min(40, (H - 64) / n), top = H / 2 - ((n - 1) * s) / 2 + 16;
      reorderTo(d, Math.round((d.y - top) / s));
      sr.textContent = d.el.textContent + " moved to position " + (plan.indexOf(d.i) + 1) + " of " + n + ".";
    } else {
      d.hx = d.x / W; d.hy = d.y / H;
    }
    kick();
  };
  d.el.addEventListener("pointerup", end);
  d.el.addEventListener("pointercancel", end);
  d.el.addEventListener("keydown", (e) => {
    const k = e.key;
    if (!["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"].includes(k)) return;
    e.preventDefault();
    if (merged) {
      if (k === "ArrowUp" || k === "ArrowDown") {
        reorderTo(d, plan.indexOf(d.i) + (k === "ArrowUp" ? -1 : 1));
        sr.textContent = d.el.textContent + ", position " + (plan.indexOf(d.i) + 1) + " of " + ideas.length + ".";
      }
    } else {
      const step = 24;
      if (k === "ArrowLeft") d.hx -= step / W;
      if (k === "ArrowRight") d.hx += step / W;
      if (k === "ArrowUp") d.hy -= step / H;
      if (k === "ArrowDown") d.hy += step / H;
      d.hx = clamp(d.hx, 0, 1); d.hy = clamp(d.hy, 0, 1);
    }
    kick();
  });
});

mergeBtn.addEventListener("click", () => {
  merged = !merged;
  root.classList.toggle("is-merged", merged);
  mergeBtn.setAttribute("aria-pressed", String(merged));
  mergeLabel.textContent = merged ? "Spill it out again" : "Merge into a plan";
  countEl.innerHTML = merged ? "<b>1</b> plan · " + ideas.length + " ideas" : "<b>" + ideas.length + "</b> ideas · drag to merge";
  ideas.forEach((d) => { d.delay = reduce ? 0 : (merged ? plan.indexOf(d.i) : ideas.length - 1 - plan.indexOf(d.i)) * 0.05; });
  sr.textContent = merged ? "Ideas merged into a plan of " + ideas.length + " items." : "Ideas spilled back onto the board.";
  kick();
});

const ro = new ResizeObserver(() => { measure(); kick(); if (!running) { step(0); paint(); } });
ro.observe(area);
const io = new IntersectionObserver((es) => {
  visible = es[es.length - 1].isIntersecting;
  if (visible) start();
}, { rootMargin: "60px" });
io.observe(root);
const beat = setInterval(() => {
  if (!root.isConnected) return dispose();
}, 1500);
function dispose() {
  if (disposed) return;
  disposed = true; running = false;
  cancelAnimationFrame(raf); clearInterval(beat); io.disconnect(); ro.disconnect();
}
